def show_structure(root, max_files_per_folder=5):
    root = Path(root)

    for current_path, dirs, files in os.walk(root):
        current_path = Path(current_path)

        relative = current_path.relative_to(root)

        level = len(relative.parts)

        indent = "    " * level

        print(f"{indent}{current_path.name}/")

        for file in sorted(files)[:max_files_per_folder]:
            print(f"{indent}    └── {file}")

        if len(files) > max_files_per_folder:
            print(f"{indent}    ... and {len(files) - max_files_per_folder} more files")


