IMAGE_EXTENSIONS = {".jpg", ".jpeg", ".png", ".bmp", ".webp"}

def count_images(folder):
    folder = Path(folder)

    counts = Counter()

    for file in folder.rglob("*"):
        if file.is_file() and file.suffix.lower() in IMAGE_EXTENSIONS:
            counts[file.suffix.lower()] += 1

    return counts


