import json
from pathlib import Path
from collections import Counter

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")

datasets = {
    "Car damages dataset": project_dir / "Car damages dataset",
    "Car parts dataset": project_dir / "Car parts dataset"
}

for dataset_name, dataset_path in datasets.items():

    print("\n" + "=" * 70)
    print(dataset_name.upper())
    print("=" * 70)

    # Check meta.json
    meta_file = dataset_path / "meta.json"

    if meta_file.exists():

        with open(meta_file, "r", encoding="utf-8") as f:
            meta = json.load(f)

        print("\nMETA.JSON FOUND")
        print("Top-level keys:", list(meta.keys()))

        classes = meta.get("classes", [])

        print("Number of metadata classes:", len(classes))

        if classes:
            print("\nMetadata classes:")
            for cls in classes:
                print(
                    f"- {cls.get('title')} "
                    f"(shape: {cls.get('shape')})"
                )

    else:
        print("\nNo meta.json found.")

    # Find annotation files
    dataset_ann_files = list(dataset_path.rglob("ann/*.json"))

    print("\nAnnotation files:", len(dataset_ann_files))

    # Extract classes from annotations
    counts = Counter()

    for ann_file in dataset_ann_files:

        try:
            with open(ann_file, "r", encoding="utf-8") as f:
                annotation = json.load(f)

            for obj in annotation.get("objects", []):
                title = obj.get("classTitle")

                if title:
                    counts[title] += 1

        except Exception:
            pass

    print("Unique annotation classes:", len(counts))

    if counts:
        print("\nAnnotation classes:")
        for cls, count in counts.most_common():
            print(f"{cls:30} : {count}")

# STEP 22 — CHECK IMAGE ↔ ANNOTATION MATCHING

from pathlib import Path

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")

datasets = {
    "Car damages dataset": project_dir / "Car damages dataset",
    "Car parts dataset": project_dir / "Car parts dataset"
}

image_extensions = {".jpg", ".jpeg", ".png", ".bmp", ".webp"}

for dataset_name, dataset_path in datasets.items():

    print("\n" + "=" * 70)
    print(dataset_name.upper())
    print("=" * 70)

    # Find all images
    image_files = [
        p for p in dataset_path.rglob("*")
        if p.is_file() and p.suffix.lower() in image_extensions
    ]

    # Find annotation files
    ann_files_dataset = list(dataset_path.rglob("ann/*.json"))

    image_names = {p.name for p in image_files}

    matched = 0
    unmatched = []

    for ann_file in ann_files_dataset:

        # Example:
        # Car damages 100.png.json
        # Remove final .json
        image_name = ann_file.name[:-5]

        if image_name in image_names:
            matched += 1
        else:
            unmatched.append(image_name)

    print("Total images:", len(image_files))
    print("Total annotation files:", len(ann_files_dataset))
    print("Matched annotations:", matched)
    print("Unmatched annotations:", len(unmatched))

    if unmatched:
        print("\nFirst 10 unmatched annotation images:")
        for name in unmatched[:10]:
            print("-", name)

    print("\nMatching percentage:",
          round((matched / len(ann_files_dataset)) * 100, 2)
          if ann_files_dataset else 0,
          "%")

# STEP 23 — CHECK ANNOTATION DIMENSIONS AGAINST ACTUAL IMAGES

from pathlib import Path
from PIL import Image

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")

datasets = {
    "Car damages dataset": project_dir / "Car damages dataset",
    "Car parts dataset": project_dir / "Car parts dataset"
}

for dataset_name, dataset_path in datasets.items():

    print("\n" + "=" * 70)
    print(dataset_name.upper())
    print("=" * 70)

    ann_files_dataset = list(dataset_path.rglob("ann/*.json"))

    matched = 0
    mismatched = 0
    errors = 0

    examples = []

    for ann_file in ann_files_dataset:

        try:
            # Read annotation
            with open(ann_file, "r", encoding="utf-8") as f:
                annotation = __import__("json").load(f)

            # Annotation image size
            size_info = annotation.get("size", {})

            ann_width = size_info.get("width")
            ann_height = size_info.get("height")

            # Corresponding image
            image_name = ann_file.name[:-5]

            image_matches = list(dataset_path.rglob(image_name))

            if not image_matches:
                errors += 1
                continue

            image_path = image_matches[0]

            # Actual image size
            with Image.open(image_path) as img:
                actual_width, actual_height = img.size

            if (ann_width, ann_height) == (actual_width, actual_height):
                matched += 1
            else:
                mismatched += 1

                if len(examples) < 5:
                    examples.append(
                        (
                            image_name,
                            (ann_width, ann_height),
                            (actual_width, actual_height)
                        )
                    )

        except Exception:
            errors += 1

    print("Total annotation files:", len(ann_files_dataset))
    print("Dimension matches:", matched)
    print("Dimension mismatches:", mismatched)
    print("Errors:", errors)

    total_checked = matched + mismatched

    if total_checked:
        print(
            "Dimension match percentage:",
            round((matched / total_checked) * 100, 2),
            "%"
        )

    if examples:
        print("\nFirst dimension mismatches:")
        for name, ann_size, actual_size in examples:
            print("\nImage:", name)
            print("Annotation size:", ann_size)
            print("Actual image size:", actual_size)

# STEP 24 — INSPECT CAR PARTS DIMENSION MISMATCH

import json
from pathlib import Path
from PIL import Image
import matplotlib.pyplot as plt

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")
dataset_path = project_dir / "Car parts dataset"

ann_files_dataset = list(dataset_path.rglob("ann/*.json"))

shown = 0

for ann_file in ann_files_dataset:

    try:
        with open(ann_file, "r", encoding="utf-8") as f:
            annotation = json.load(f)

        size_info = annotation.get("size", {})

        ann_width = size_info.get("width")
        ann_height = size_info.get("height")

        image_name = ann_file.name[:-5]

        image_matches = list(dataset_path.rglob(image_name))

        if not image_matches:
            continue

        image_path = image_matches[0]

        with Image.open(image_path) as img:
            actual_width, actual_height = img.size
            image = img.convert("RGB")

        # Only inspect mismatches
        if (ann_width, ann_height) != (actual_width, actual_height):

            objects = annotation.get("objects", [])

            print("=" * 70)
            print("IMAGE:", image_name)
            print("ANNOTATION SIZE:", (ann_width, ann_height))
            print("ACTUAL SIZE:", (actual_width, actual_height))
            print("NUMBER OF OBJECTS:", len(objects))

            # Find maximum annotation coordinate
            max_x = 0
            max_y = 0

            for obj in objects:

                points = obj.get("points", {})
                exterior = points.get("exterior", [])

                for x, y in exterior:
                    max_x = max(max_x, x)
                    max_y = max(max_y, y)

            print("Maximum annotation X:", max_x)
            print("Maximum annotation Y:", max_y)

            # Display image
            plt.figure(figsize=(14, 5))
            plt.imshow(image)
            plt.title(
                f"{image_name}\n"
                f"Annotation: {ann_width}×{ann_height} | "
                f"Actual: {actual_width}×{actual_height}"
            )
            plt.axis("off")
            plt.show()

            shown += 1

            if shown >= 3:
                break

    except Exception as e:
        print("Error:", e)

print("\nInspected mismatched images:", shown)

# STEP 25 — ANALYZE CAR PARTS WIDTH SCALING

import json
from pathlib import Path
from PIL import Image
from collections import Counter

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")
dataset_path = project_dir / "Car parts dataset"

ann_files_dataset = list(dataset_path.rglob("ann/*.json"))

ratios = []
details = []

for ann_file in ann_files_dataset:

    try:
        with open(ann_file, "r", encoding="utf-8") as f:
            annotation = json.load(f)

        size_info = annotation.get("size", {})

        ann_width = size_info.get("width")
        ann_height = size_info.get("height")

        image_name = ann_file.name[:-5]

        image_matches = list(dataset_path.rglob(image_name))

        if not image_matches:
            continue

        image_path = image_matches[0]

        with Image.open(image_path) as img:
            actual_width, actual_height = img.size

        if ann_width and actual_width:

            ratio = actual_width / ann_width

            if abs(ratio - 1.0) > 0.01:
                ratios.append(ratio)

                details.append({
                    "image": image_name,
                    "ann_width": ann_width,
                    "actual_width": actual_width,
                    "ratio": ratio
                })

    except Exception:
        pass

print("=" * 70)
print("CAR PARTS WIDTH SCALING ANALYSIS")
print("=" * 70)

print("\nMismatched files analyzed:", len(ratios))

if ratios:

    print("\nMinimum ratio:", round(min(ratios), 4))
    print("Maximum ratio:", round(max(ratios), 4))
    print("Average ratio:", round(sum(ratios) / len(ratios), 4))

    # Group ratios after rounding
    ratio_groups = Counter(round(r, 2) for r in ratios)

    print("\nMost common width ratios:")

    for ratio, count in ratio_groups.most_common(15):
        print(f"{ratio:6.2f} × : {count} images")

    print("\nFirst 10 examples:")

    for item in details[:10]:
        print(
            f"{item['image']} | "
            f"Annotation: {item['ann_width']} | "
            f"Actual: {item['actual_width']} | "
            f"Ratio: {item['ratio']:.4f}"
        )

# STEP 26 — VALIDATE CORRECTED POLYGON COORDINATES

import json
from pathlib import Path
from PIL import Image
import matplotlib.pyplot as plt

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")
dataset_path = project_dir / "Car parts dataset"

ann_files_dataset = list(dataset_path.rglob("ann/*.json"))

shown = 0

for ann_file in ann_files_dataset:

    try:
        with open(ann_file, "r", encoding="utf-8") as f:
            annotation = json.load(f)

        ann_width = annotation["size"]["width"]
        ann_height = annotation["size"]["height"]

        image_name = ann_file.name[:-5]
        image_matches = list(dataset_path.rglob(image_name))

        if not image_matches:
            continue

        image_path = image_matches[0]

        with Image.open(image_path) as img:
            actual_width, actual_height = img.size
            image = img.convert("RGB")

        # Only test mismatched images
        if (ann_width, ann_height) == (actual_width, actual_height):
            continue

        # Scaling factor
        scale_x = actual_width / ann_width

        print("=" * 70)
        print("IMAGE:", image_name)
        print("Original annotation size:", (ann_width, ann_height))
        print("Actual image size:", (actual_width, actual_height))
        print("X scaling factor:", round(scale_x, 6))

        plt.figure(figsize=(14, 6))
        plt.imshow(image)

        # Draw corrected polygons
        for obj in annotation.get("objects", []):

            points = obj.get("points", {})
            exterior = points.get("exterior", [])

            if len(exterior) < 2:
                continue

            corrected_points = [
                (x * scale_x, y)
                for x, y in exterior
            ]

            xs = [p[0] for p in corrected_points]
            ys = [p[1] for p in corrected_points]

            # Close polygon
            xs.append(xs[0])
            ys.append(ys[0])

            plt.plot(xs, ys, linewidth=1.5)

            # Label near first point
            plt.text(
                xs[0],
                ys[0],
                obj.get("classTitle", ""),
                fontsize=7
            )

        plt.title(
            f"Corrected Polygon Preview\n"
            f"{image_name} | Scale X = {scale_x:.4f}"
        )

        plt.xlim(0, actual_width)
        plt.ylim(actual_height, 0)
        plt.axis("off")
        plt.show()

        shown += 1

        if shown >= 3:
            break

    except Exception as e:
        print("Error:", ann_file)
        print(e)

print("\nCorrected polygon previews:", shown)

# STEP 27 — CREATE CORRECTED CAR PARTS ANNOTATIONS

import json
import shutil
from pathlib import Path
from PIL import Image

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")

source_dir = project_dir / "Car parts dataset"
processed_dir = project_dir / "outputs" / "corrected_car_parts"

processed_dir.mkdir(parents=True, exist_ok=True)

ann_files_dataset = list(source_dir.rglob("ann/*.json"))

corrected_count = 0
unchanged_count = 0
error_count = 0

for ann_file in ann_files_dataset:

    try:
        # Load annotation
        with open(ann_file, "r", encoding="utf-8") as f:
            annotation = json.load(f)

        ann_width = annotation["size"]["width"]
        ann_height = annotation["size"]["height"]

        image_name = ann_file.name[:-5]

        image_matches = list(source_dir.rglob(image_name))

        if not image_matches:
            error_count += 1
            continue

        image_path = image_matches[0]

        with Image.open(image_path) as img:
            actual_width, actual_height = img.size

        # Correct polygon X coordinates if required
        if ann_width != actual_width:

            scale_x = actual_width / ann_width

            for obj in annotation.get("objects", []):

                points = obj.get("points", {})
                exterior = points.get("exterior", [])

                corrected_exterior = [
                    [x * scale_x, y]
                    for x, y in exterior
                ]

                points["exterior"] = corrected_exterior

            # Update annotation size
            annotation["size"]["width"] = actual_width
            annotation["size"]["height"] = actual_height

            corrected_count += 1

        else:
            unchanged_count += 1

        # Preserve relative annotation structure
        relative_path = ann_file.relative_to(source_dir)

        output_file = processed_dir / relative_path
        output_file.parent.mkdir(parents=True, exist_ok=True)

        with open(output_file, "w", encoding="utf-8") as f:
            json.dump(annotation, f, indent=2)

    except Exception as e:

        error_count += 1
        print("Error:", ann_file)
        print(e)

print("=" * 70)
print("CORRECTED CAR PARTS DATASET")
print("=" * 70)

print("Total annotation files:", len(ann_files_dataset))
print("Corrected annotations:", corrected_count)
print("Already matching:", unchanged_count)
print("Errors:", error_count)

print("\nOutput directory:")
print(processed_dir)

