import json
from pathlib import Path
from PIL import Image
import matplotlib.pyplot as plt

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")

source_dir = project_dir / "Car parts dataset"
corrected_dir = project_dir / "outputs" / "corrected_car_parts"

ann_files = list(corrected_dir.rglob("ann/*.json"))

shown = 0

for ann_file in ann_files:

    try:
        with open(ann_file, "r", encoding="utf-8") as f:
            annotation = json.load(f)

        image_name = ann_file.name[:-5]

        image_matches = list(source_dir.rglob(image_name))

        if not image_matches:
            continue

        image_path = image_matches[0]

        with Image.open(image_path) as img:
            image = img.convert("RGB")
            width, height = img.size

        plt.figure(figsize=(14, 7))
        plt.imshow(image)

        for obj in annotation.get("objects", []):

            points = obj.get("points", {})
            exterior = points.get("exterior", [])

            if len(exterior) < 3:
                continue

            xs = [p[0] for p in exterior]
            ys = [p[1] for p in exterior]

            # Close polygon
            xs.append(xs[0])
            ys.append(ys[0])

            plt.plot(xs, ys, linewidth=2)

            plt.text(
                xs[0],
                ys[0],
                obj.get("classTitle", ""),
                fontsize=8
            )

        plt.title(f"Corrected Annotation: {image_name}")
        plt.xlim(0, width)
        plt.ylim(height, 0)
        plt.axis("off")
        plt.show()

        shown += 1

        if shown >= 5:
            break

    except Exception as e:
        print("Error:", ann_file)
        print(e)

print("=" * 70)
print("VISUALIZATION COMPLETE")
print("Images visualized:", shown)
print("=" * 70)

