import json
from pathlib import Path
from PIL import Image
import matplotlib.pyplot as plt

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")
dataset_path = project_dir / "Car parts dataset"

ann_files = list(dataset_path.rglob("ann/*.json"))

shown = 0

print("=" * 70)
print("DOUBLE-WIDTH IMAGE VERIFICATION")
print("=" * 70)

for ann_file in ann_files:

    try:
        with open(ann_file, "r", encoding="utf-8") as f:
            annotation = json.load(f)

        ann_width = annotation["size"]["width"]
        ann_height = annotation["size"]["height"]

        image_name = ann_file.name[:-5]

        image_matches = list(dataset_path.rglob(image_name))

        if not image_matches:
            continue

        image_path = image_matches[0]

        with Image.open(image_path) as img:
            actual_width, actual_height = img.size
            image = img.convert("RGB")

        # Only inspect the mismatched images
        if actual_width <= ann_width * 1.9:
            continue

        # Approximate half width
        half_width = actual_width // 2

        left_half = image.crop((0, 0, half_width, actual_height))
        right_half = image.crop(
            (half_width, 0, actual_width, actual_height)
        )

        print("\n" + "=" * 70)
        print("IMAGE:", image_name)
        print("Annotation size:", (ann_width, ann_height))
        print("Actual size:", (actual_width, actual_height))
        print("Approximate half width:", half_width)

        # Display left and right halves
        fig, axes = plt.subplots(1, 2, figsize=(16, 5))

        axes[0].imshow(left_half)
        axes[0].set_title("LEFT HALF")
        axes[0].axis("off")

        axes[1].imshow(right_half)
        axes[1].set_title("RIGHT HALF")
        axes[1].axis("off")

        plt.suptitle(image_name)
        plt.show()

        shown += 1

        if shown >= 3:
            break

    except Exception as e:
        print("Error:", ann_file)
        print(e)

print("\nImages inspected:", shown)

# STEP 31 — CREATE CLEAN CAR PARTS DATASET

import json
import shutil
from pathlib import Path
from PIL import Image

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")

source_dir = project_dir / "Car parts dataset"
clean_dir = project_dir / "outputs" / "clean_car_parts"

images_out = clean_dir / "images"
ann_out = clean_dir / "ann"

images_out.mkdir(parents=True, exist_ok=True)
ann_out.mkdir(parents=True, exist_ok=True)

ann_files = list(source_dir.rglob("ann/*.json"))

cropped_count = 0
normal_count = 0
error_count = 0

for ann_file in ann_files:

    try:
        # Read original annotation
        with open(ann_file, "r", encoding="utf-8") as f:
            annotation = json.load(f)

        ann_width = annotation["size"]["width"]
        ann_height = annotation["size"]["height"]

        # Corresponding image name
        image_name = ann_file.name[:-5]

        image_matches = list(source_dir.rglob(image_name))

        if not image_matches:
            error_count += 1
            continue

        image_path = image_matches[0]

        with Image.open(image_path) as img:
            image = img.convert("RGB")
            actual_width, actual_height = image.size

            # ---------------------------------------------------------
            # CASE 1: Double-width image
            # ---------------------------------------------------------
            if actual_width > ann_width * 1.9:

                # Use the right half, where the corrected polygons
                # were visually aligned.
                start_x = actual_width - ann_width

                clean_image = image.crop(
                    (
                        start_x,
                        0,
                        actual_width,
                        actual_height
                    )
                )

                cropped_count += 1

            # ---------------------------------------------------------
            # CASE 2: Already normal-sized image
            # ---------------------------------------------------------
            else:

                clean_image = image.copy()
                normal_count += 1

        # Save image
        output_image = images_out / image_name
        clean_image.save(output_image)

        # -------------------------------------------------------------
        # Keep ORIGINAL annotation coordinates.
        # They correspond to the single-width annotation image.
        # -------------------------------------------------------------

        annotation["size"]["width"] = ann_width
        annotation["size"]["height"] = ann_height

        output_ann = ann_out / ann_file.name

        with open(output_ann, "w", encoding="utf-8") as f:
            json.dump(annotation, f, indent=2)

    except Exception as e:

        error_count += 1

        print("Error:", ann_file)
        print(e)

print("=" * 70)
print("CLEAN CAR PARTS DATASET CREATED")
print("=" * 70)

print("Total annotation files:", len(ann_files))
print("Double-width images cropped:", cropped_count)
print("Normal images copied:", normal_count)
print("Errors:", error_count)

print("\nTotal clean images:",
      len(list(images_out.iterdir())))

print("Total clean annotations:",
      len(list(ann_out.iterdir())))

print("\nOutput directory:")
print(clean_dir)

# STEP 32 — VALIDATE CLEAN DATASET POLYGON COORDINATES

import json
from pathlib import Path
from PIL import Image

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")

clean_dir = project_dir / "outputs" / "clean_car_parts"
images_dir = clean_dir / "images"
ann_dir = clean_dir / "ann"

ann_files = list(ann_dir.glob("*.json"))

valid_annotations = 0
invalid_annotations = 0
invalid_objects = 0
missing_images = 0

for ann_file in ann_files:

    try:
        with open(ann_file, "r", encoding="utf-8") as f:
            annotation = json.load(f)

        image_name = ann_file.name[:-5]
        image_path = images_dir / image_name

        if not image_path.exists():
            missing_images += 1
            continue

        with Image.open(image_path) as img:
            width, height = img.size

        annotation_valid = True

        for obj in annotation.get("objects", []):

            points = obj.get("points", {})
            exterior = points.get("exterior", [])

            for x, y in exterior:

                if not (0 <= x <= width and 0 <= y <= height):
                    invalid_objects += 1
                    annotation_valid = False
                    break

        if annotation_valid:
            valid_annotations += 1
        else:
            invalid_annotations += 1

    except Exception as e:
        invalid_annotations += 1
        print("Error:", ann_file)
        print(e)

print("=" * 70)
print("CLEAN DATASET POLYGON VALIDATION")
print("=" * 70)

print("Total annotations:", len(ann_files))
print("Valid annotations:", valid_annotations)
print("Invalid annotations:", invalid_annotations)
print("Invalid objects:", invalid_objects)
print("Missing images:", missing_images)

if len(ann_files) > 0:
    print(
        "Valid annotation percentage:",
        round((valid_annotations / len(ann_files)) * 100, 2),
        "%"
    )

