from pathlib import Path
from collections import Counter

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")

# ---------------------------------------------------------
# 1. Clean Car Parts Dataset
# ---------------------------------------------------------

clean_images = list(
    (project_dir / "outputs" / "clean_car_parts" / "images").glob("*")
)

clean_annotations = list(
    (project_dir / "outputs" / "clean_car_parts" / "ann").glob("*.json")
)

# ---------------------------------------------------------
# 2. Car Damages Dataset
# ---------------------------------------------------------

damage_images = list(
    (project_dir / "Car damages dataset").rglob("*")
)

damage_images = [
    p for p in damage_images
    if p.is_file()
    and p.suffix.lower() in [".jpg", ".jpeg", ".png"]
]

damage_annotations = list(
    (project_dir / "Car damages dataset").rglob("ann/*.json")
)

# ---------------------------------------------------------
# 3. Car Parts Damage Classes
# ---------------------------------------------------------

class_counts = Counter()

for ann_file in clean_annotations:

    try:
        import json

        with open(ann_file, "r", encoding="utf-8") as f:
            annotation = json.load(f)

        for obj in annotation.get("objects", []):

            cls = obj.get("classTitle")

            if cls:
                class_counts[cls] += 1

    except Exception:
        pass

# ---------------------------------------------------------
# PRINT FINAL INVENTORY
# ---------------------------------------------------------

print("=" * 70)
print("FINAL PROJECT DATASET INVENTORY")
print("=" * 70)

print("\nCLEAN CAR PARTS DATASET")
print("-" * 70)
print("Images:", len(clean_images))
print("Annotations:", len(clean_annotations))

print("\nCAR DAMAGES DATASET")
print("-" * 70)
print("Images:", len(damage_images))
print("Annotations:", len(damage_annotations))

print("\nDAMAGE CLASSES IN CLEAN CAR PARTS DATASET")
print("-" * 70)

damage_classes = [
    "Missing part",
    "Broken part",
    "Scratch",
    "Cracked",
    "Dent",
    "Flaking",
    "Paint chip",
    "Corrosion"
]

for cls in damage_classes:
    print(f"{cls:20} : {class_counts.get(cls, 0)}")

print("\nTOTAL DAMAGE OBJECTS:",
      sum(class_counts.get(cls, 0) for cls in damage_classes))

print("\n" + "=" * 70)
print("DATASET INVENTORY COMPLETE")
print("=" * 70)

