# STEP 39 — STRATIFIED TRAIN / VALIDATION / TEST SPLIT

import pandas as pd
from pathlib import Path
from sklearn.model_selection import train_test_split

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")

clean_csv_path = (
    project_dir
    / "outputs"
    / "classification_dataset"
    / "classification_labels.csv"
)

split_dir = (
    project_dir
    / "outputs"
    / "classification_dataset"
    / "splits"
)

split_dir.mkdir(parents=True, exist_ok=True)

# Load cleaned dataset
df = pd.read_csv(clean_csv_path)

print("=" * 70)
print("CREATING STRATIFIED DATASET SPLITS")
print("=" * 70)

print("Total images:", len(df))

# ---------------------------------------------------------
# STEP 1: 70% TRAIN + 30% TEMPORARY
# ---------------------------------------------------------

train_df, temp_df = train_test_split(
    df,
    test_size=0.30,
    stratify=df["classes"],
    random_state=42
)

# ---------------------------------------------------------
# STEP 2: Split remaining 30% into
# 15% VALIDATION + 15% TEST
# ---------------------------------------------------------

val_df, test_df = train_test_split(
    temp_df,
    test_size=0.50,
    stratify=temp_df["classes"],
    random_state=42
)

# Reset indexes
train_df = train_df.reset_index(drop=True)
val_df = val_df.reset_index(drop=True)
test_df = test_df.reset_index(drop=True)

# ---------------------------------------------------------
# SAVE SPLITS
# ---------------------------------------------------------

train_path = split_dir / "train.csv"
val_path = split_dir / "validation.csv"
test_path = split_dir / "test.csv"

train_df.to_csv(train_path, index=False)
val_df.to_csv(val_path, index=False)
test_df.to_csv(test_path, index=False)

# ---------------------------------------------------------
# DISPLAY RESULTS
# ---------------------------------------------------------

print("\nDataset sizes:")
print("Training   :", len(train_df))
print("Validation :", len(val_df))
print("Testing    :", len(test_df))

print("\nPercentages:")
print("Training   :", round(len(train_df) / len(df) * 100, 2), "%")
print("Validation :", round(len(val_df) / len(df) * 100, 2), "%")
print("Testing    :", round(len(test_df) / len(df) * 100, 2), "%")

print("\n" + "-" * 70)
print("TRAIN CLASS DISTRIBUTION")
print("-" * 70)
print(train_df["classes"].value_counts())

print("\n" + "-" * 70)
print("VALIDATION CLASS DISTRIBUTION")
print("-" * 70)
print(val_df["classes"].value_counts())

print("\n" + "-" * 70)
print("TEST CLASS DISTRIBUTION")
print("-" * 70)
print(test_df["classes"].value_counts())

print("\nFiles saved:")
print(train_path)
print(val_path)
print(test_path)

print("\n" + "=" * 70)

# STEP 40 — CHECK IMAGE OVERLAP BETWEEN TRAIN / VALIDATION / TEST

import pandas as pd
from pathlib import Path

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")

split_dir = (
    project_dir
    / "outputs"
    / "classification_dataset"
    / "splits"
)

train_df = pd.read_csv(split_dir / "train.csv")
val_df = pd.read_csv(split_dir / "validation.csv")
test_df = pd.read_csv(split_dir / "test.csv")

train_images = set(train_df["image"])
val_images = set(val_df["image"])
test_images = set(test_df["image"])

train_val_overlap = train_images.intersection(val_images)
train_test_overlap = train_images.intersection(test_images)
val_test_overlap = val_images.intersection(test_images)

print("=" * 70)
print("DATA LEAKAGE / IMAGE OVERLAP CHECK")
print("=" * 70)

print("Training images   :", len(train_images))
print("Validation images :", len(val_images))
print("Testing images    :", len(test_images))

print("\nOverlap results:")
print("Train ∩ Validation :", len(train_val_overlap))
print("Train ∩ Test       :", len(train_test_overlap))
print("Validation ∩ Test  :", len(val_test_overlap))

total_overlap = (
    len(train_val_overlap)
    + len(train_test_overlap)
    + len(val_test_overlap)
)

print("\nTotal overlap:", total_overlap)

if total_overlap == 0:
    print("\n✅ NO DATA LEAKAGE DETECTED")
    print("Each image exists in only one dataset split.")
else:
    print("\n⚠️ DATA LEAKAGE DETECTED")

    if train_val_overlap:
        print("\nTrain/Validation overlapping images:")
        print(sorted(train_val_overlap))

    if train_test_overlap:
        print("\nTrain/Test overlapping images:")
        print(sorted(train_test_overlap))

    if val_test_overlap:
        print("\nValidation/Test overlapping images:")
        print(sorted(val_test_overlap))

print("\n" + "=" * 70)

# STEP 41 — FINAL IMAGE AVAILABILITY CHECK FOR ALL SPLITS

import pandas as pd
from pathlib import Path
from PIL import Image

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")

split_dir = (
    project_dir
    / "outputs"
    / "classification_dataset"
    / "splits"
)

# Load split files
train_df = pd.read_csv(split_dir / "train.csv")
val_df = pd.read_csv(split_dir / "validation.csv")
test_df = pd.read_csv(split_dir / "test.csv")

splits = {
    "TRAIN": train_df,
    "VALIDATION": val_df,
    "TEST": test_df
}

print("=" * 70)
print("FINAL IMAGE AVAILABILITY AND READABILITY CHECK")
print("=" * 70)

total_missing = 0
total_unreadable = 0

for split_name, df in splits.items():

    missing = []
    unreadable = []

    for image_ref in df["image"]:

        image_path = project_dir / image_ref

        if not image_path.exists():
            missing.append(str(image_ref))
            continue

        try:
            with Image.open(image_path) as img:
                img.verify()
        except Exception:
            unreadable.append(str(image_ref))

    print(f"\n{split_name}")
    print("-" * 40)
    print("Images:", len(df))
    print("Missing:", len(missing))
    print("Unreadable:", len(unreadable))

    total_missing += len(missing)
    total_unreadable += len(unreadable)

print("\n" + "=" * 70)
print("FINAL RESULT")
print("=" * 70)

print("Total missing images:", total_missing)
print("Total unreadable images:", total_unreadable)

if total_missing == 0 and total_unreadable == 0:
    print("\n✅ ALL SPLIT IMAGES EXIST AND ARE READABLE")
    print("Classification dataset is ready for Phase 2.")
else:
    print("\n⚠️ IMAGE PROBLEMS FOUND")
    print("Review the missing/unreadable images before training.")

print("=" * 70)

