import pandas as pd
import json
from pathlib import Path
from sklearn.model_selection import train_test_split

# ---------------------------------------------------------
# PATHS
# ---------------------------------------------------------

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")

csv_path = project_dir / "data.csv"

classification_dir = (
    project_dir / "outputs" / "classification_dataset"
)

split_dir = classification_dir / "splits"

classification_dir.mkdir(parents=True, exist_ok=True)
split_dir.mkdir(parents=True, exist_ok=True)

# ---------------------------------------------------------
# LOAD ORIGINAL DATA
# ---------------------------------------------------------

df = pd.read_csv(csv_path)

print("=" * 70)
print("RECREATING CLASSIFICATION FILES")
print("=" * 70)

print("Original CSV rows:", len(df))
print("Original unique images:", df["image"].nunique())

# ---------------------------------------------------------
# REMOVE DUPLICATE IMAGE ENTRIES
# ---------------------------------------------------------

df_clean = (
    df.drop_duplicates(
        subset=["image"],
        keep="first"
    )
    .reset_index(drop=True)
)

# Remove unnecessary CSV index column
if "Unnamed: 0" in df_clean.columns:
    df_clean = df_clean.drop(columns=["Unnamed: 0"])

print("\nClean dataset:")
print("Images:", len(df_clean))
print("Classes:", df_clean["classes"].nunique())

# ---------------------------------------------------------
# FIXED CLASS MAPPING
# ---------------------------------------------------------

classes = sorted(df_clean["classes"].unique())

class_to_idx = {
    name: idx
    for idx, name in enumerate(classes)
}

idx_to_class = {
    idx: name
    for name, idx in class_to_idx.items()
}

df_clean["label"] = df_clean["classes"].map(class_to_idx)

# ---------------------------------------------------------
# 70 / 15 / 15 STRATIFIED SPLIT
# ---------------------------------------------------------

train_df, temp_df = train_test_split(
    df_clean,
    test_size=0.30,
    stratify=df_clean["label"],
    random_state=42
)

val_df, test_df = train_test_split(
    temp_df,
    test_size=0.50,
    stratify=temp_df["label"],
    random_state=42
)

train_df = train_df.reset_index(drop=True)
val_df = val_df.reset_index(drop=True)
test_df = test_df.reset_index(drop=True)

# ---------------------------------------------------------
# SAVE FILES
# ---------------------------------------------------------

clean_csv = classification_dir / "classification_labels.csv"
train_csv = split_dir / "train.csv"
val_csv = split_dir / "validation.csv"
test_csv = split_dir / "test.csv"
mapping_json = classification_dir / "class_mapping.json"

df_clean.to_csv(clean_csv, index=False)
train_df.to_csv(train_csv, index=False)
val_df.to_csv(val_csv, index=False)
test_df.to_csv(test_csv, index=False)

mapping = {
    "class_to_idx": class_to_idx,
    "idx_to_class": {
        str(k): v
        for k, v in idx_to_class.items()
    }
}

with open(mapping_json, "w") as f:
    json.dump(mapping, f, indent=4)

# ---------------------------------------------------------
# RESULTS
# ---------------------------------------------------------

print("\n" + "-" * 70)
print("CLASS MAPPING")
print("-" * 70)

for idx, name in idx_to_class.items():
    print(f"{idx} -> {name}")

print("\n" + "-" * 70)
print("DATASET SPLITS")
print("-" * 70)

print("Training   :", len(train_df))
print("Validation :", len(val_df))
print("Testing    :", len(test_df))

print("\n" + "-" * 70)
print("FILES CREATED")
print("-" * 70)

print(clean_csv)
print(train_csv)
print(val_csv)
print(test_csv)
print(mapping_json)

print("\n" + "=" * 70)
print("✅ CLASSIFICATION FILES RECREATED")
