# STEP 45 — PYTORCH DATASET AND DATALOADERS

import pandas as pd
import torch
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms
from PIL import Image
from pathlib import Path

# ---------------------------------------------------------
# PATHS
# ---------------------------------------------------------

project_dir = Path("/content/drive/MyDrive/END SEM PROJECT-DL")

split_dir = (
    project_dir
    / "outputs"
    / "classification_dataset"
    / "splits"
)

# ---------------------------------------------------------
# LOAD SPLITS
# ---------------------------------------------------------

train_df = pd.read_csv(split_dir / "train.csv")
val_df = pd.read_csv(split_dir / "validation.csv")
test_df = pd.read_csv(split_dir / "test.csv")

# ---------------------------------------------------------
# DEVICE
# ---------------------------------------------------------

device = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

print("=" * 70)
print("PYTORCH DATA PIPELINE")
print("=" * 70)

print("Device:", device)

if torch.cuda.is_available():
    print("GPU:", torch.cuda.get_device_name(0))
else:
    print("GPU not available — using CPU")

# ---------------------------------------------------------
# IMAGE TRANSFORMS
# ---------------------------------------------------------

train_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.RandomHorizontalFlip(p=0.5),
    transforms.RandomRotation(10),
    transforms.ColorJitter(
        brightness=0.15,
        contrast=0.15
    ),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

eval_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

# ---------------------------------------------------------
# CUSTOM DATASET
# ---------------------------------------------------------

class CarDamageDataset(Dataset):

    def __init__(self, dataframe, root_dir, transform=None):

        self.dataframe = dataframe.reset_index(drop=True)
        self.root_dir = Path(root_dir)
        self.transform = transform

    def __len__(self):
        return len(self.dataframe)

    def __getitem__(self, index):

        row = self.dataframe.iloc[index]

        image_path = self.root_dir / row["image"]

        image = Image.open(image_path).convert("RGB")

        label = int(row["label"])

        if self.transform:
            image = self.transform(image)

        return image, label


# ---------------------------------------------------------
# CREATE DATASETS
# ---------------------------------------------------------

train_dataset = CarDamageDataset(
    train_df,
    project_dir,
    train_transform
)

val_dataset = CarDamageDataset(
    val_df,
    project_dir,
    eval_transform
)

test_dataset = CarDamageDataset(
    test_df,
    project_dir,
    eval_transform
)

# ---------------------------------------------------------
# CREATE DATALOADERS
# ---------------------------------------------------------

BATCH_SIZE = 32

train_loader = DataLoader(
    train_dataset,
    batch_size=BATCH_SIZE,
    shuffle=True,
    num_workers=2,
    pin_memory=torch.cuda.is_available()
)

val_loader = DataLoader(
    val_dataset,
    batch_size=BATCH_SIZE,
    shuffle=False,
    num_workers=2,
    pin_memory=torch.cuda.is_available()
)

test_loader = DataLoader(
    test_dataset,
    batch_size=BATCH_SIZE,
    shuffle=False,
    num_workers=2,
    pin_memory=torch.cuda.is_available()
)

# ---------------------------------------------------------
# VERIFY ONE BATCH
# ---------------------------------------------------------

images, labels = next(iter(train_loader))

print("\n" + "-" * 70)
print("BATCH VERIFICATION")
print("-" * 70)

print("Image batch shape :", images.shape)
print("Label batch shape :", labels.shape)
print("Image data type   :", images.dtype)
print("Label data type   :", labels.dtype)

print("\nBatch size:", images.size(0))
print("Number of classes:", 8)

print("\nLabel values in batch:")
print(sorted(labels.unique().tolist()))

print("\n" + "=" * 70)
print("✅ PYTORCH DATA PIPELINE READY")
print("=" * 70)

