# STEP 47 — CALCULATE CLASS WEIGHTS

import torch
import numpy as np
from sklearn.utils.class_weight import compute_class_weight

# ---------------------------------------------------------
# CLASS INFORMATION
# ---------------------------------------------------------

NUM_CLASSES = 8

class_names = [
    "bumper_dent",
    "bumper_scratch",
    "door_dent",
    "door_scratch",
    "glass_shatter",
    "head_lamp",
    "tail_lamp",
    "unknown"
]

# ---------------------------------------------------------
# GET TRAINING LABELS
# ---------------------------------------------------------

train_labels = train_df["label"].values

# ---------------------------------------------------------
# CALCULATE BALANCED CLASS WEIGHTS
# ---------------------------------------------------------

class_weights = compute_class_weight(
    class_weight="balanced",
    classes=np.arange(NUM_CLASSES),
    y=train_labels
)

class_weights = torch.tensor(
    class_weights,
    dtype=torch.float32
).to(device)

# ---------------------------------------------------------
# DISPLAY RESULTS
# ---------------------------------------------------------

print("=" * 70)
print("CLASS WEIGHTS")
print("=" * 70)

for i, (name, weight) in enumerate(
    zip(class_names, class_weights.cpu().numpy())
):
    count = int((train_df["label"] == i).sum())

    print(
        f"{i}: {name:<18} "
        f"Samples={count:<4} "
        f"Weight={weight:.4f}"
    )

print("\nClass weights tensor:")
print(class_weights)

print("\n" + "=" * 70)
print("✅ CLASS WEIGHTS CALCULATED")
print("=" * 70)

# STEP 48 — LOSS FUNCTION, OPTIMIZER AND LEARNING-RATE SCHEDULER

import torch.nn as nn
import torch.optim as optim

# ---------------------------------------------------------
# LOSS FUNCTION
# ---------------------------------------------------------

criterion = nn.CrossEntropyLoss(
    weight=class_weights
)

# ---------------------------------------------------------
# OPTIMIZER
# ---------------------------------------------------------

LEARNING_RATE = 0.0001

optimizer = optim.AdamW(
    model.parameters(),
    lr=LEARNING_RATE,
    weight_decay=1e-4
)

# ---------------------------------------------------------
# LEARNING-RATE SCHEDULER
# ---------------------------------------------------------

scheduler = optim.lr_scheduler.ReduceLROnPlateau(
    optimizer,
    mode="min",
    factor=0.5,
    patience=2
)

# ---------------------------------------------------------
# CONFIGURATION
# ---------------------------------------------------------

EPOCHS = 10

print("=" * 70)
print("TRAINING CONFIGURATION")
print("=" * 70)

print("Loss function       : Weighted CrossEntropyLoss")
print("Optimizer           : AdamW")
print("Learning rate       :", LEARNING_RATE)
print("Weight decay        :", 1e-4)
print("Scheduler           : ReduceLROnPlateau")
print("Scheduler factor    :", 0.5)
print("Scheduler patience  :", 2)
print("Epochs              :", EPOCHS)

print("\n" + "=" * 70)
print("✅ TRAINING CONFIGURATION READY")
print("=" * 70)

# STEP 49 — TRAIN EFFICIENTNET-B0

import time
import copy
import torch

# ---------------------------------------------------------
# TRAINING SETTINGS
# ---------------------------------------------------------

best_val_loss = float("inf")
best_model_state = copy.deepcopy(model.state_dict())

history = {
    "train_loss": [],
    "val_loss": [],
    "train_acc": [],
    "val_acc": [],
    "learning_rate": []
}

# ---------------------------------------------------------
# SAVE PATH
# ---------------------------------------------------------

model_dir = (
    project_dir
    / "outputs"
    / "classification_model"
)

model_dir.mkdir(
    parents=True,
    exist_ok=True
)

best_model_path = (
    model_dir
    / "best_efficientnet_b0.pth"
)

print("=" * 70)
print("STARTING EFFICIENTNET-B0 TRAINING")
print("=" * 70)

print("Training samples   :", len(train_dataset))
print("Validation samples :", len(val_dataset))
print("Batch size         :", BATCH_SIZE)
print("Epochs             :", EPOCHS)
print("Device             :", device)

# ---------------------------------------------------------
# TRAINING LOOP
# ---------------------------------------------------------

for epoch in range(EPOCHS):

    start_time = time.time()

    # =====================================================
    # TRAIN
    # =====================================================

    model.train()

    running_loss = 0.0
    correct = 0
    total = 0

    for images, labels in train_loader:

        images = images.to(device, non_blocking=True)
        labels = labels.to(device, non_blocking=True)

        optimizer.zero_grad()

        outputs = model(images)

        loss = criterion(outputs, labels)

        loss.backward()

        optimizer.step()

        running_loss += loss.item() * images.size(0)

        predictions = outputs.argmax(dim=1)

        correct += (
            predictions == labels
        ).sum().item()

        total += labels.size(0)

    train_loss = running_loss / total
    train_acc = correct / total

    # =====================================================
    # VALIDATION
    # =====================================================

    model.eval()

    val_running_loss = 0.0
    val_correct = 0
    val_total = 0

    with torch.no_grad():

        for images, labels in val_loader:

            images = images.to(
                device,
                non_blocking=True
            )

            labels = labels.to(
                device,
                non_blocking=True
            )

            outputs = model(images)

            loss = criterion(
                outputs,
                labels
            )

            val_running_loss += (
                loss.item() * images.size(0)
            )

            predictions = outputs.argmax(dim=1)

            val_correct += (
                predictions == labels
            ).sum().item()

            val_total += labels.size(0)

    val_loss = val_running_loss / val_total
    val_acc = val_correct / val_total

    # =====================================================
    # LEARNING RATE SCHEDULER
    # =====================================================

    scheduler.step(val_loss)

    current_lr = optimizer.param_groups[0]["lr"]

    # =====================================================
    # SAVE HISTORY
    # =====================================================

    history["train_loss"].append(train_loss)
    history["val_loss"].append(val_loss)
    history["train_acc"].append(train_acc)
    history["val_acc"].append(val_acc)
    history["learning_rate"].append(current_lr)

    # =====================================================
    # SAVE BEST MODEL
    # =====================================================

    if val_loss < best_val_loss:

        best_val_loss = val_loss

        best_model_state = copy.deepcopy(
            model.state_dict()
        )

        torch.save(
            {
                "model_state_dict": model.state_dict(),
                "val_loss": val_loss,
                "val_accuracy": val_acc,
                "epoch": epoch + 1,
                "class_names": class_names
            },
            best_model_path
        )

        best_marker = " ★ BEST"

    else:
        best_marker = ""

    # =====================================================
    # EPOCH OUTPUT
    # =====================================================

    elapsed = time.time() - start_time

    print(
        f"Epoch [{epoch+1:02d}/{EPOCHS}] | "
        f"Train Loss: {train_loss:.4f} | "
        f"Train Acc: {train_acc:.4f} | "
        f"Val Loss: {val_loss:.4f} | "
        f"Val Acc: {val_acc:.4f} | "
        f"LR: {current_lr:.6f} | "
        f"Time: {elapsed:.1f}s"
        f"{best_marker}"
    )

# ---------------------------------------------------------
# RESTORE BEST MODEL
# ---------------------------------------------------------

model.load_state_dict(best_model_state)

print("\n" + "=" * 70)
print("✅ TRAINING COMPLETED")
print("=" * 70)

print(
    f"Best validation loss: {best_val_loss:.4f}"
)

print(
    f"Best model saved to:\n{best_model_path}"
)

# STEP 50 — FINAL TEST SET EVALUATION

import torch
import numpy as np
from sklearn.metrics import (
    accuracy_score,
    precision_recall_fscore_support,
    classification_report,
    confusion_matrix
)

# ---------------------------------------------------------
# LOAD BEST CHECKPOINT
# ---------------------------------------------------------

checkpoint = torch.load(
    best_model_path,
    map_location=device
)

model.load_state_dict(
    checkpoint["model_state_dict"]
)

model = model.to(device)
model.eval()

# ---------------------------------------------------------
# TEST PREDICTIONS
# ---------------------------------------------------------

all_predictions = []
all_labels = []

with torch.no_grad():

    for images, labels in test_loader:

        images = images.to(
            device,
            non_blocking=True
        )

        outputs = model(images)

        predictions = outputs.argmax(
            dim=1
        )

        all_predictions.extend(
            predictions.cpu().numpy()
        )

        all_labels.extend(
            labels.numpy()
        )

# Convert to NumPy
all_predictions = np.array(all_predictions)
all_labels = np.array(all_labels)

# ---------------------------------------------------------
# OVERALL METRICS
# ---------------------------------------------------------

test_accuracy = accuracy_score(
    all_labels,
    all_predictions
)

precision, recall, f1, _ = precision_recall_fscore_support(
    all_labels,
    all_predictions,
    average="weighted",
    zero_division=0
)

macro_precision, macro_recall, macro_f1, _ = (
    precision_recall_fscore_support(
        all_labels,
        all_predictions,
        average="macro",
        zero_division=0
    )
)

# ---------------------------------------------------------
# DISPLAY RESULTS
# ---------------------------------------------------------

print("=" * 70)
print("FINAL TEST SET EVALUATION")
print("=" * 70)

print("Test samples       :", len(all_labels))
print(f"Test Accuracy      : {test_accuracy:.4f}")
print(f"Weighted Precision : {precision:.4f}")
print(f"Weighted Recall    : {recall:.4f}")
print(f"Weighted F1-Score  : {f1:.4f}")

print(f"\nMacro Precision    : {macro_precision:.4f}")
print(f"Macro Recall       : {macro_recall:.4f}")
print(f"Macro F1-Score     : {macro_f1:.4f}")

# ---------------------------------------------------------
# CLASSIFICATION REPORT
# ---------------------------------------------------------

print("\n" + "=" * 70)
print("CLASSIFICATION REPORT")
print("=" * 70)

print(
    classification_report(
        all_labels,
        all_predictions,
        labels=np.arange(NUM_CLASSES),
        target_names=class_names,
        zero_division=0
    )
)

