# STEP 52 — CONVERT POLYGONS INTO BINARY DAMAGE MASKS

import json
import numpy as np
from PIL import Image, ImageDraw
from pathlib import Path

# ---------------------------------------------------------
# PATHS
# ---------------------------------------------------------

clean_dir = (
    project_dir
    / "outputs"
    / "clean_car_parts"
)

image_dir = clean_dir / "images"
ann_dir = clean_dir / "ann"

mask_dir = (
    project_dir
    / "outputs"
    / "segmentation_dataset"
    / "masks"
)

mask_dir.mkdir(
    parents=True,
    exist_ok=True
)

# ---------------------------------------------------------
# PROCESS ANNOTATIONS
# ---------------------------------------------------------

processed = 0
failed = 0
total_polygons = 0

for json_file in sorted(ann_dir.glob("*.json")):

    try:

        # ---------------------------------------------
        # LOAD ANNOTATION
        # ---------------------------------------------

        with open(json_file, "r") as f:
            data = json.load(f)

        # ---------------------------------------------
        # FIND CORRESPONDING IMAGE
        # ---------------------------------------------

        image_name = json_file.name[:-5]
        image_path = image_dir / image_name

        if not image_path.exists():
            failed += 1
            continue

        # ---------------------------------------------
        # GET IMAGE SIZE
        # ---------------------------------------------

        image = Image.open(image_path)

        width, height = image.size

        # ---------------------------------------------
        # CREATE EMPTY MASK
        # ---------------------------------------------

        mask = Image.new(
            "L",
            (width, height),
            0
        )

        draw = ImageDraw.Draw(mask)

        # ---------------------------------------------
        # DRAW DAMAGE POLYGONS
        # ---------------------------------------------

        for obj in data.get("objects", []):

            geometry_type = obj.get("geometryType")

            if geometry_type != "polygon":
                continue

            points_data = (
                obj
                .get("points", {})
                .get("exterior", [])
            )

            if len(points_data) < 3:
                continue

            polygon = [
                (
                    int(round(point[0])),
                    int(round(point[1]))
                )
                for point in points_data
            ]

            draw.polygon(
                polygon,
                fill=1
            )

            total_polygons += 1

        # ---------------------------------------------
        # SAVE MASK
        # ---------------------------------------------

        mask_path = mask_dir / image_name

        mask.save(mask_path)

        processed += 1

    except Exception as e:

        failed += 1

# ---------------------------------------------------------
# DISPLAY RESULTS
# ---------------------------------------------------------

print("=" * 70)
print("BINARY DAMAGE MASK GENERATION")
print("=" * 70)

print("Images processed :", processed)
print("Images failed    :", failed)
print("Polygons drawn   :", total_polygons)
print("Masks created    :", len(list(mask_dir.iterdir())))

print("\nMask values:")
print("0 = Background")
print("1 = Damage")

print("\nMask directory:")
print(mask_dir)

print("\n" + "=" * 70)

if (
    processed == 814
    and failed == 0
    and len(list(mask_dir.iterdir())) == 814
):
    print("✅ ALL DAMAGE MASKS CREATED")
else:
    print("⚠️ MASK GENERATION REQUIRES REVIEW")

print("=" * 70)

