# STEP 55 — PYTORCH SEGMENTATION DATASET AND DATALOADERS

import pandas as pd
import numpy as np
import torch
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms
from PIL import Image

# ---------------------------------------------------------
# LOAD SPLITS
# ---------------------------------------------------------

train_seg_df = pd.read_csv(train_seg_path)
val_seg_df = pd.read_csv(val_seg_path)
test_seg_df = pd.read_csv(test_seg_path)

# ---------------------------------------------------------
# IMAGE TRANSFORMS
# ---------------------------------------------------------

SEG_SIZE = 256

image_transform = transforms.Compose([
    transforms.Resize(
        (SEG_SIZE, SEG_SIZE)
    ),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

mask_transform = transforms.Compose([
    transforms.Resize(
        (SEG_SIZE, SEG_SIZE),
        interpolation=transforms.InterpolationMode.NEAREST
    )
])

# ---------------------------------------------------------
# CUSTOM SEGMENTATION DATASET
# ---------------------------------------------------------

class CarDamageSegmentationDataset(Dataset):

    def __init__(
        self,
        dataframe,
        image_transform=None,
        mask_transform=None
    ):

        self.dataframe = dataframe.reset_index(
            drop=True
        )

        self.image_transform = image_transform
        self.mask_transform = mask_transform

    def __len__(self):
        return len(self.dataframe)

    def __getitem__(self, index):

        row = self.dataframe.iloc[index]

        # ---------------------------------------------
        # LOAD IMAGE
        # ---------------------------------------------

        image = Image.open(
            row["image"]
        ).convert("RGB")

        # ---------------------------------------------
        # LOAD MASK
        # ---------------------------------------------

        mask = Image.open(
            row["mask"]
        ).convert("L")

        # ---------------------------------------------
        # RESIZE IMAGE
        # ---------------------------------------------

        if self.image_transform:
            image = self.image_transform(image)

        # ---------------------------------------------
        # RESIZE MASK
        # ---------------------------------------------

        if self.mask_transform:
            mask = self.mask_transform(mask)

        # ---------------------------------------------
        # CONVERT MASK TO BINARY TENSOR
        # ---------------------------------------------

        mask = np.array(mask)

        mask = (mask > 0).astype(
            np.float32
        )

        mask = torch.from_numpy(
            mask
        ).unsqueeze(0)

        return image, mask


# ---------------------------------------------------------
# CREATE DATASETS
# ---------------------------------------------------------

train_seg_dataset = CarDamageSegmentationDataset(
    train_seg_df,
    image_transform,
    mask_transform
)

val_seg_dataset = CarDamageSegmentationDataset(
    val_seg_df,
    image_transform,
    mask_transform
)

test_seg_dataset = CarDamageSegmentationDataset(
    test_seg_df,
    image_transform,
    mask_transform
)

# ---------------------------------------------------------
# CREATE DATALOADERS
# ---------------------------------------------------------

SEG_BATCH_SIZE = 16

train_seg_loader = DataLoader(
    train_seg_dataset,
    batch_size=SEG_BATCH_SIZE,
    shuffle=True,
    num_workers=2,
    pin_memory=torch.cuda.is_available()
)

val_seg_loader = DataLoader(
    val_seg_dataset,
    batch_size=SEG_BATCH_SIZE,
    shuffle=False,
    num_workers=2,
    pin_memory=torch.cuda.is_available()
)

test_seg_loader = DataLoader(
    test_seg_dataset,
    batch_size=SEG_BATCH_SIZE,
    shuffle=False,
    num_workers=2,
    pin_memory=torch.cuda.is_available()
)

# ---------------------------------------------------------
# VERIFY ONE BATCH
# ---------------------------------------------------------

images, masks = next(
    iter(train_seg_loader)
)

print("=" * 70)
print("SEGMENTATION DATA PIPELINE")
print("=" * 70)

print("Device:", device)

print("\nImage batch shape:")
print(images.shape)

print("\nMask batch shape:")
print(masks.shape)

print("\nImage dtype:", images.dtype)
print("Mask dtype :", masks.dtype)

print("\nMask minimum:", masks.min().item())
print("Mask maximum:", masks.max().item())

print("\nBatch size:", images.size(0))
print("Image size:", SEG_SIZE, "x", SEG_SIZE)

print("\n" + "=" * 70)
print("✅ SEGMENTATION DATA PIPELINE READY")
