# STEP 58 — TRAIN U-NET SEGMENTATION MODEL

import os
import time
import torch

# ============================================================
# DICE SCORE FUNCTION
# ============================================================

def dice_score(logits, targets, threshold=0.5, smooth=1.0):

    probabilities = torch.sigmoid(logits)

    predictions = (
        probabilities > threshold
    ).float()

    predictions = predictions.view(
        predictions.size(0), -1
    )

    targets = targets.view(
        targets.size(0), -1
    )

    intersection = (
        predictions * targets
    ).sum(dim=1)

    dice = (
        (2.0 * intersection + smooth)
        /
        (
            predictions.sum(dim=1)
            +
            targets.sum(dim=1)
            +
            smooth
        )
    )

    return dice.mean().item()


# ============================================================
# CONFIGURATION
# ============================================================

NUM_EPOCHS = 10

best_val_loss = float("inf")
best_val_dice = 0.0

seg_history = []


# ============================================================
# MODEL SAVE DIRECTORY
# ============================================================

seg_model_dir = (
    "/content/drive/MyDrive/"
    "END SEM PROJECT-DL/outputs/segmentation_model"
)

os.makedirs(
    seg_model_dir,
    exist_ok=True
)

best_seg_model_path = os.path.join(
    seg_model_dir,
    "best_unet_resnet18.pth"
)


# ============================================================
# TRAINING LOOP
# ============================================================

print("=" * 70)
print("U-NET SEGMENTATION TRAINING")
print("=" * 70)

print("Device       :", device)
print("Epochs       :", NUM_EPOCHS)
print("Train images :", len(train_seg_dataset))
print("Val images   :", len(val_seg_dataset))
print("Batch size   :", 16)
print("Best model   :", best_seg_model_path)

print("=" * 70)


for epoch in range(NUM_EPOCHS):

    start_time = time.time()

    # --------------------------------------------------------
    # TRAINING
    # --------------------------------------------------------

    seg_model.train()

    train_loss_total = 0.0
    train_dice_total = 0.0
    train_batches = 0

    for images, masks in train_seg_loader:

        images = images.to(
            device,
            non_blocking=True
        )

        masks = masks.to(
            device,
            non_blocking=True
        )

        # Clear gradients
        seg_optimizer.zero_grad(
            set_to_none=True
        )

        # Forward pass
        logits = seg_model(images)

        # Loss
        loss = seg_criterion(
            logits,
            masks
        )

        # Backpropagation
        loss.backward()

        # Optimizer step
        seg_optimizer.step()

        # Metrics
        batch_dice = dice_score(
            logits.detach(),
            masks
        )

        train_loss_total += loss.item()
        train_dice_total += batch_dice
        train_batches += 1


    train_loss = (
        train_loss_total /
        train_batches
    )

    train_dice = (
        train_dice_total /
        train_batches
    )


    # --------------------------------------------------------
    # VALIDATION
    # --------------------------------------------------------

    seg_model.eval()

    val_loss_total = 0.0
    val_dice_total = 0.0
    val_batches = 0

    with torch.no_grad():

        for images, masks in val_seg_loader:

            images = images.to(
                device,
                non_blocking=True
            )

            masks = masks.to(
                device,
                non_blocking=True
            )

            # Forward pass
            logits = seg_model(images)

            # Loss
            loss = seg_criterion(
                logits,
                masks
            )

            # Dice
            batch_dice = dice_score(
                logits,
                masks
            )

            val_loss_total += loss.item()
            val_dice_total += batch_dice
            val_batches += 1


    val_loss = (
        val_loss_total /
        val_batches
    )

    val_dice = (
        val_dice_total /
        val_batches
    )


    # --------------------------------------------------------
    # LEARNING RATE SCHEDULER
    # --------------------------------------------------------

    seg_scheduler.step(
        val_loss
    )


    current_lr = (
        seg_optimizer.param_groups[0]["lr"]
    )


    # --------------------------------------------------------
    # SAVE BEST MODEL
    # --------------------------------------------------------

    is_best = val_loss < best_val_loss

    if is_best:

        best_val_loss = val_loss
        best_val_dice = val_dice

        torch.save(
            {
                "epoch": epoch + 1,
                "model_state_dict":
                    seg_model.state_dict(),
                "optimizer_state_dict":
                    seg_optimizer.state_dict(),
                "val_loss":
                    val_loss,
                "val_dice":
                    val_dice
            },
            best_seg_model_path
        )


    # --------------------------------------------------------
    # SAVE HISTORY
    # --------------------------------------------------------

    epoch_time = time.time() - start_time

    seg_history.append(
        {
            "epoch": epoch + 1,
            "train_loss": train_loss,
            "train_dice": train_dice,
            "val_loss": val_loss,
            "val_dice": val_dice,
            "learning_rate": current_lr
        }
    )


    # --------------------------------------------------------
    # PRINT RESULTS
    # --------------------------------------------------------

    marker = " ★ BEST" if is_best else ""

    print(
        f"Epoch {epoch + 1:02d}/{NUM_EPOCHS} | "
        f"Train Loss: {train_loss:.4f} | "
        f"Train Dice: {train_dice:.4f} | "
        f"Val Loss: {val_loss:.4f} | "
        f"Val Dice: {val_dice:.4f} | "
        f"LR: {current_lr:.6f} | "
        f"Time: {epoch_time:.1f}s"
        f"{marker}"
    )


# ============================================================
# FINAL TRAINING SUMMARY
# ============================================================

print("\n" + "=" * 70)
print("✅ U-NET TRAINING COMPLETED")
print("=" * 70)

print(
    f"Best Validation Loss : "
    f"{best_val_loss:.4f}"
)

print(
    f"Best Validation Dice : "
    f"{best_val_dice:.4f}"
)

print(
    "Best Model Saved At   :"
)

print(
    best_seg_model_path
)

print("=" * 70)

# STEP 59 — TEST SET EVALUATION

import torch
import numpy as np
from sklearn.metrics import confusion_matrix

# ============================================================
# LOAD BEST MODEL
# ============================================================

checkpoint = torch.load(
    best_seg_model_path,
    map_location=device
)

seg_model.load_state_dict(
    checkpoint["model_state_dict"]
)

seg_model.to(device)
seg_model.eval()


# ============================================================
# METRIC STORAGE
# ============================================================

total_dice = 0.0
total_iou = 0.0
total_precision = 0.0
total_recall = 0.0

num_batches = 0

all_predictions = []
all_targets = []


# ============================================================
# TEST EVALUATION
# ============================================================

with torch.no_grad():

    for images, masks in test_seg_loader:

        images = images.to(
            device,
            non_blocking=True
        )

        masks = masks.to(
            device,
            non_blocking=True
        )

        # ----------------------------------------------------
        # MODEL PREDICTION
        # ----------------------------------------------------

        logits = seg_model(images)

        probabilities = torch.sigmoid(
            logits
        )

        predictions = (
            probabilities >= 0.5
        ).float()


        # ----------------------------------------------------
        # FLATTEN
        # ----------------------------------------------------

        pred_flat = predictions.view(
            predictions.size(0), -1
        )

        mask_flat = masks.view(
            masks.size(0), -1
        )


        # ----------------------------------------------------
        # PER-IMAGE METRICS
        # ----------------------------------------------------

        for i in range(
            predictions.size(0)
        ):

            pred = pred_flat[i]
            target = mask_flat[i]

            tp = (
                (pred == 1) &
                (target == 1)
            ).sum().float()

            fp = (
                (pred == 1) &
                (target == 0)
            ).sum().float()

            fn = (
                (pred == 0) &
                (target == 1)
            ).sum().float()

            # Dice
            dice = (
                (2 * tp + 1.0) /
                (
                    2 * tp +
                    fp +
                    fn +
                    1.0
                )
            )

            # IoU
            iou = (
                (tp + 1.0) /
                (
                    tp +
                    fp +
                    fn +
                    1.0
                )
            )

            # Precision
            precision = (
                (tp + 1.0) /
                (
                    tp +
                    fp +
                    1.0
                )
            )

            # Recall
            recall = (
                (tp + 1.0) /
                (
                    tp +
                    fn +
                    1.0
                )
            )

            total_dice += dice.item()
            total_iou += iou.item()
            total_precision += precision.item()
            total_recall += recall.item()

            num_batches += 1


# ============================================================
# FINAL METRICS
# ============================================================

test_dice = (
    total_dice / num_batches
)

test_iou = (
    total_iou / num_batches
)

test_precision = (
    total_precision / num_batches
)

test_recall = (
    total_recall / num_batches
)


# ============================================================
# PRINT RESULTS
# ============================================================

print("=" * 70)
print("SEGMENTATION TEST SET EVALUATION")
print("=" * 70)

print(
    "Test images        :",
    len(test_seg_dataset)
)

print(
    "Dice Score         :",
    f"{test_dice:.4f}"
)

print(
    "IoU Score          :",
    f"{test_iou:.4f}"
)

print(
    "Precision          :",
    f"{test_precision:.4f}"
)

print(
    "Recall             :",
    f"{test_recall:.4f}"
)

print("=" * 70)

print(
    "Best validation Dice:",
    f"{checkpoint['val_dice']:.4f}"
)

print(
    "Best validation loss:",
    f"{checkpoint['val_loss']:.4f}"
)

print("=" * 70)

print("✅ TEST SET EVALUATION COMPLETED")
