import torch
import pandas as pd
import numpy as np
import os

# ============================================================
# LOAD BEST SEGMENTATION MODEL
# ============================================================

checkpoint = torch.load(
    best_seg_model_path,
    map_location=device
)

seg_model.load_state_dict(
    checkpoint["model_state_dict"]
)

seg_model.to(device)
seg_model.eval()


# ============================================================
# FEATURE EXTRACTION FUNCTION
# ============================================================

def calculate_damage_features(masks, predictions):

    results = []

    batch_size = masks.shape[0]

    for i in range(batch_size):

        # ----------------------------------------------------
        # GROUND TRUTH MASK
        # ----------------------------------------------------

        gt_mask = (
            masks[i, 0]
            .cpu()
            .numpy()
        )

        # ----------------------------------------------------
        # PREDICTED MASK
        # ----------------------------------------------------

        pred_mask = (
            predictions[i, 0]
            .cpu()
            .numpy()
        )

        # ----------------------------------------------------
        # PIXEL COUNTS
        # ----------------------------------------------------

        total_pixels = (
            pred_mask.shape[0] *
            pred_mask.shape[1]
        )

        predicted_damage_pixels = int(
            (pred_mask > 0).sum()
        )

        ground_truth_damage_pixels = int(
            (gt_mask > 0).sum()
        )

        # ----------------------------------------------------
        # DAMAGE PERCENTAGE
        # ----------------------------------------------------

        predicted_damage_percentage = (
            predicted_damage_pixels /
            total_pixels
        ) * 100

        ground_truth_damage_percentage = (
            ground_truth_damage_pixels /
            total_pixels
        ) * 100

        # ----------------------------------------------------
        # PROJECT-DEFINED SEVERITY
        # ----------------------------------------------------

        if predicted_damage_percentage == 0:

            severity = "No Damage"

        elif predicted_damage_percentage < 5:

            severity = "Low"

        elif predicted_damage_percentage < 15:

            severity = "Moderate"

        elif predicted_damage_percentage < 30:

            severity = "High"

        else:

            severity = "Very High"

        # ----------------------------------------------------
        # NUMERIC SEVERITY SCORE
        # ----------------------------------------------------

        severity_score_map = {

            "No Damage": 0,

            "Low": 25,

            "Moderate": 50,

            "High": 75,

            "Very High": 100
        }

        severity_score = severity_score_map[
            severity
        ]

        # ----------------------------------------------------
        # STORE FEATURES
        # ----------------------------------------------------

        results.append({

            "predicted_damage_pixels":
                predicted_damage_pixels,

            "ground_truth_damage_pixels":
                ground_truth_damage_pixels,

            "predicted_damage_percentage":
                round(
                    predicted_damage_percentage,
                    4
                ),

            "ground_truth_damage_percentage":
                round(
                    ground_truth_damage_percentage,
                    4
                ),

            "severity":
                severity,

            "severity_score":
                severity_score
        })

    return results


# ============================================================
# EXTRACT FEATURES FROM TEST SET
# ============================================================

all_results = []

with torch.no_grad():

    for images, masks in test_seg_loader:

        images = images.to(
            device,
            non_blocking=True
        )

        masks = masks.to(
            device,
            non_blocking=True
        )

        # ----------------------------------------------------
        # MODEL PREDICTION
        # ----------------------------------------------------

        logits = seg_model(images)

        probabilities = torch.sigmoid(
            logits
        )

        predictions = (
            probabilities >= 0.5
        ).float()

        # ----------------------------------------------------
        # FEATURE EXTRACTION
        # ----------------------------------------------------

        batch_results = calculate_damage_features(
            masks,
            predictions
        )

        all_results.extend(
            batch_results
        )


# ============================================================
# CREATE DATAFRAME
# ============================================================

damage_features_df = pd.DataFrame(
    all_results
)


# ============================================================
# ADD IMAGE INFORMATION
# ============================================================

damage_features_df.insert(
    0,
    "image_name",
    test_seg_df["image_name"].tolist()
)

damage_features_df.insert(
    1,
    "image_path",
    test_seg_df["image"].tolist()
)


# ============================================================
# SAVE FEATURES
# ============================================================

feature_dir = (
    "/content/drive/MyDrive/"
    "END SEM PROJECT-DL/"
    "outputs/segmentation_features"
)

os.makedirs(
    feature_dir,
    exist_ok=True
)

feature_path = os.path.join(
    feature_dir,
    "damage_area_severity_features.csv"
)

damage_features_df.to_csv(
    feature_path,
    index=False
)


# ============================================================
# DISPLAY RESULTS
# ============================================================

print("=" * 70)
print("DAMAGE AREA & SEVERITY FEATURE EXTRACTION")
print("=" * 70)

print(
    "Test images processed:",
    len(damage_features_df)
)

print(
    "Feature columns:",
    len(damage_features_df.columns)
)

print("\nSample results:")

print(
    damage_features_df.head(10).to_string(
        index=False
    )
)

print("\nSeverity distribution:")

print(
    damage_features_df[
        "severity"
    ].value_counts()
)

print("\nAverage predicted damage percentage:")

print(
    f"{damage_features_df['predicted_damage_percentage'].mean():.2f}%"
)

print("\nMaximum predicted damage percentage:")

print(
    f"{damage_features_df['predicted_damage_percentage'].max():.2f}%"
)

print("\nFeatures saved to:")

print(feature_path)

