classification_df = pd.read_csv(classification_test_path)
segmentation_df = pd.read_csv(segmentation_features_path)

# ---------------------------------------------------------
# EXTRACT IMAGE IDENTIFIERS
# ---------------------------------------------------------
# Classification examples:
# image/841.jpeg
#
# Segmentation examples:
# Car damages 1091.jpg
#
# We compare the numeric image identifier.

def extract_number(value):
    match = re.search(r'(\d+)', str(value))
    return int(match.group(1)) if match else None


classification_df["image_id"] = (
    classification_df["image"]
    .apply(extract_number)
)

segmentation_df["image_id"] = (
    segmentation_df["image_name"]
    .apply(extract_number)
)

# ---------------------------------------------------------
# FIND OVERLAP
# ---------------------------------------------------------

classification_ids = set(
    classification_df["image_id"].dropna().astype(int)
)

segmentation_ids = set(
    segmentation_df["image_id"].dropna().astype(int)
)

common_ids = classification_ids.intersection(segmentation_ids)

print(f"Classification unique image IDs: {len(classification_ids)}")
print(f"Segmentation unique image IDs: {len(segmentation_ids)}")
print(f"Common image IDs: {len(common_ids)}")

print(
    f"Classification images overlapping segmentation: "
    f"{len(common_ids)}"
)

print(
    f"Segmentation images overlapping classification: "
    f"{len(common_ids)}"
)

# ---------------------------------------------------------
# SHOW EXAMPLES
# ---------------------------------------------------------

if len(common_ids) > 0:

    print("\nSample overlapping IDs:")

    sample_ids = sorted(common_ids)[:20]

    for image_id in sample_ids:

        c = classification_df[
            classification_df["image_id"] == image_id
        ]["image"].iloc[0]

        s = segmentation_df[
            segmentation_df["image_id"] == image_id
        ]["image_name"].iloc[0]

        print(
            f"ID {image_id}: "
            f"{c}  <->  {s}"
        )

else:

    print("\nNo direct image-ID overlap detected.")

# ---------------------------------------------------------
# CLEANUP TEMPORARY COLUMN
# ---------------------------------------------------------

classification_df.drop(columns=["image_id"], inplace=True)
segmentation_df.drop(columns=["image_id"], inplace=True)

print("\n" + "=" * 70)
print("✅ IMAGE OVERLAP CHECK COMPLETED")
print("=" * 70)

import os
import json
import pandas as pd
import torch
import torch.nn as nn
from torchvision import models, transforms
from PIL import Image

print("=" * 70)
print("STEP 65 — BUILDING INTEGRATED ASSESSMENT DATASET")
print("=" * 70)

# ---------------------------------------------------------
# PATHS
# ---------------------------------------------------------

project_root = "/content/drive/MyDrive/END SEM PROJECT-DL"

classification_test_path = os.path.join(
    project_root,
    "outputs",
    "classification_dataset",
    "splits",
    "test.csv"
)

segmentation_features_path = os.path.join(
    project_root,
    "outputs",
    "segmentation_features",
    "damage_area_severity_features.csv"
)

model_path = os.path.join(
    project_root,
    "outputs",
    "classification_model",
    "best_efficientnet_b0.pth"
)

mapping_path = os.path.join(
    project_root,
    "outputs",
    "classification_dataset",
    "class_mapping.json"
)

output_dir = os.path.join(
    project_root,
    "outputs",
    "integrated_assessment"
)

os.makedirs(output_dir, exist_ok=True)

# ---------------------------------------------------------
# LOAD DATA
# ---------------------------------------------------------

classification_df = pd.read_csv(
    classification_test_path
)

segmentation_df = pd.read_csv(
    segmentation_features_path
)

# ---------------------------------------------------------
# CREATE IMAGE IDs
# ---------------------------------------------------------

classification_df["image_id"] = (
    classification_df["image"]
    .str.extract(r"(\d+)")[0]
    .astype(int)
)

segmentation_df["image_id"] = (
    segmentation_df["image_name"]
    .str.extract(r"(\d+)")[0]
    .astype(int)
)

# ---------------------------------------------------------
# FIND COMMON IMAGES
# ---------------------------------------------------------

common_ids = sorted(
    set(classification_df["image_id"])
    .intersection(
        set(segmentation_df["image_id"])
    )
)

print(f"Common images: {len(common_ids)}")

# ---------------------------------------------------------
# KEEP ONLY COMMON IMAGES
# ---------------------------------------------------------

classification_common = classification_df[
    classification_df["image_id"].isin(common_ids)
].copy()

segmentation_common = segmentation_df[
    segmentation_df["image_id"].isin(common_ids)
].copy()

# ---------------------------------------------------------
# MERGE
# ---------------------------------------------------------

integrated_df = pd.merge(
    classification_common,
    segmentation_common,
    on="image_id",
    how="inner",
    suffixes=("_classification", "_segmentation")
)

print(
    f"Merged integrated samples: "
    f"{len(integrated_df)}"
)

print("\nMerged columns:")
print(integrated_df.columns.tolist())

# ---------------------------------------------------------
# LOAD CLASS MAPPING
# ---------------------------------------------------------

with open(mapping_path, "r") as f:
    mapping_data = json.load(f)

if "class_to_idx" in mapping_data:

    class_mapping = {
        int(index): class_name
        for class_name, index
        in mapping_data["class_to_idx"].items()
    }

elif "idx_to_class" in mapping_data:

    class_mapping = {
        int(index): class_name
        for index, class_name
        in mapping_data["idx_to_class"].items()
    }

else:

    class_mapping = {
        int(index): class_name
        for class_name, index
        in mapping_data.items()
    }

print("\nFinal index-to-class mapping:")
print(class_mapping)

# ---------------------------------------------------------
# MAP CLASSIFICATION LABEL
# ---------------------------------------------------------

integrated_df["classification_name"] = (
    integrated_df["label"]
    .map(class_mapping)
)

# ---------------------------------------------------------
# LOAD EFFICIENTNET-B0
# ---------------------------------------------------------

device = torch.device(
    "cuda"
    if torch.cuda.is_available()
    else "cpu"
)

model = models.efficientnet_b0(
    weights=None
)

model.classifier[1] = nn.Linear(
    model.classifier[1].in_features,
    8
)

checkpoint = torch.load(
    model_path,
    map_location=device
)

if (
    isinstance(checkpoint, dict)
    and "model_state_dict" in checkpoint
):

    model.load_state_dict(
        checkpoint["model_state_dict"]
    )

else:

    model.load_state_dict(
        checkpoint
    )

model = model.to(device)
model.eval()

print(f"\nDevice: {device}")
print(
    "EfficientNet-B0 loaded successfully."
)

# ---------------------------------------------------------
# TRANSFORMATION
# ---------------------------------------------------------

transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

# ---------------------------------------------------------
# CLASSIFICATION CONFIDENCE
# ---------------------------------------------------------

confidences = []

for _, row in integrated_df.iterrows():

    # IMPORTANT:
    # The classification dataset column is "image"
    image_path = os.path.join(
        project_root,
        row["image"]
    )

    image = Image.open(
        image_path
    ).convert("RGB")

    tensor = (
        transform(image)
        .unsqueeze(0)
        .to(device)
    )

    with torch.no_grad():

        output = model(tensor)

        probabilities = torch.softmax(
            output,
            dim=1
        )

        predicted_label = torch.argmax(
            probabilities,
            dim=1
        ).item()

        confidence = probabilities[
            0,
            predicted_label
        ].item()

    confidences.append(
        confidence
    )

integrated_df[
    "classification_confidence"
] = confidences

# ---------------------------------------------------------
# FINAL FEATURE TABLE
# ---------------------------------------------------------

final_df = integrated_df[
    [
        "image_id",
        "image",
        "image_name",
        "classes",
        "label",
        "classification_name",
        "classification_confidence",
        "predicted_damage_percentage",
        "ground_truth_damage_percentage",
        "severity",
        "severity_score"
    ]
].copy()

# Rename image column for clarity
final_df.rename(
    columns={
        "image": "classification_image"
    },
    inplace=True
)

# ---------------------------------------------------------
# SAVE
# ---------------------------------------------------------

output_path = os.path.join(
    output_dir,
    "integrated_assessment_features.csv"
)

final_df.to_csv(
    output_path,
    index=False
)

# ---------------------------------------------------------
# RESULTS
# ---------------------------------------------------------

print("\nIntegrated dataset shape:")
print(final_df.shape)

print("\nIntegrated features:")
print(
    final_df.columns.tolist()
)

print("\nSample integrated results:")

print(
    final_df.head(10)
    .to_string(index=False)
)

print("\nClassification distribution:")

print(
    final_df[
        "classification_name"
    ].value_counts()
)

print("\nSeverity distribution:")

print(
    final_df[
        "severity"
    ].value_counts()
)

print(
    "\nAverage classification confidence:"
)

print(
    f"{final_df['classification_confidence'].mean() * 100:.2f}%"
)

print("\nSaved to:")
print(output_path)

print("\n" + "=" * 70)
print(
    "✅ INTEGRATED ASSESSMENT DATASET CREATED"
)
print("=" * 70)

import os
import pandas as pd
import numpy as np

print("=" * 70)
print("STEP 66 — AI ASSESSMENT SCORE GENERATION")
print("=" * 70)

# ---------------------------------------------------------
# PATH
# ---------------------------------------------------------

project_root = "/content/drive/MyDrive/END SEM PROJECT-DL"

input_path = os.path.join(
    project_root,
    "outputs",
    "integrated_assessment",
    "integrated_assessment_features.csv"
)

output_dir = os.path.join(
    project_root,
    "outputs",
    "integrated_assessment"
)

os.makedirs(output_dir, exist_ok=True)

# ---------------------------------------------------------
# LOAD INTEGRATED FEATURES
# ---------------------------------------------------------

df = pd.read_csv(input_path)

print(f"Input samples: {len(df)}")

# ---------------------------------------------------------
# DAMAGE SCORE
# ---------------------------------------------------------
# Predicted damage percentage is converted to a 0–100 scale.
# Values above 100 are clipped for safety.

df["damage_score"] = (
    df["predicted_damage_percentage"]
    .clip(0, 100)
)

# ---------------------------------------------------------
# CONFIDENCE SCORE
# ---------------------------------------------------------

df["confidence_score"] = (
    df["classification_confidence"] * 100
).clip(0, 100)

# ---------------------------------------------------------
# WEIGHTED ASSESSMENT SCORE
# ---------------------------------------------------------

df["assessment_score"] = (
    0.60 * df["damage_score"]
    +
    0.40 * df["confidence_score"]
)

df["assessment_score"] = (
    df["assessment_score"]
    .clip(0, 100)
    .round(2)
)

# ---------------------------------------------------------
# SCORE CATEGORY
# ---------------------------------------------------------

def score_category(score):

    if score < 25:
        return "Low Assessment"

    elif score < 50:
        return "Moderate Assessment"

    elif score < 75:
        return "High Assessment"

    else:
        return "Very High Assessment"


df["assessment_category"] = (
    df["assessment_score"]
    .apply(score_category)
)

# ---------------------------------------------------------
# DISPLAY
# ---------------------------------------------------------

print("\nAssessment score results:")

print(
    df[
        [
            "image_id",
            "classification_name",
            "classification_confidence",
            "predicted_damage_percentage",
            "severity",
            "damage_score",
            "confidence_score",
            "assessment_score",
            "assessment_category"
        ]
    ].to_string(index=False)
)

# ---------------------------------------------------------
# SUMMARY
# ---------------------------------------------------------

print("\n" + "-" * 70)

print(
    f"Average assessment score: "
    f"{df['assessment_score'].mean():.2f}"
)

print(
    f"Minimum assessment score: "
    f"{df['assessment_score'].min():.2f}"
)

print(
    f"Maximum assessment score: "
    f"{df['assessment_score'].max():.2f}"
)

print("\nAssessment category distribution:")

print(
    df["assessment_category"]
    .value_counts()
)

# ---------------------------------------------------------
# SAVE
# ---------------------------------------------------------

output_path = os.path.join(
    output_dir,
    "final_assessment_scores.csv"
)

df.to_csv(
    output_path,
    index=False
)

print("\nSaved to:")
print(output_path)

print("\n" + "=" * 70)
print("✅ 0–100 AI ASSESSMENT SCORES GENERATED")
print("=" * 70)

