import os
import pandas as pd

print("=" * 70)
print("STEP 68 — PROJECT-DEFINED INSURANCE ELIGIBILITY")
print("=" * 70)

# ---------------------------------------------------------
# PATH
# ---------------------------------------------------------

project_root = "/content/drive/MyDrive/END SEM PROJECT-DL"

input_path = os.path.join(
    project_root,
    "outputs",
    "integrated_assessment",
    "final_assessment_scores.csv"
)

output_dir = os.path.join(
    project_root,
    "outputs",
    "integrated_assessment"
)

os.makedirs(output_dir, exist_ok=True)

# ---------------------------------------------------------
# LOAD ASSESSMENT SCORES
# ---------------------------------------------------------

df = pd.read_csv(input_path)

# ---------------------------------------------------------
# PROJECT-DEFINED ELIGIBILITY THRESHOLD
# ---------------------------------------------------------

ELIGIBILITY_THRESHOLD = 25.0

df["insurance_eligibility"] = df[
    "assessment_score"
].apply(
    lambda score:
        "Insurance Eligible"
        if score >= ELIGIBILITY_THRESHOLD
        else "Not Eligible"
)

# ---------------------------------------------------------
# ELIGIBILITY REASON
# ---------------------------------------------------------

def eligibility_reason(row):

    if row["insurance_eligibility"] == "Insurance Eligible":

        return (
            f"Assessment score {row['assessment_score']:.2f} "
            f"is at or above the project threshold of "
            f"{ELIGIBILITY_THRESHOLD:.0f}."
        )

    else:

        return (
            f"Assessment score {row['assessment_score']:.2f} "
            f"is below the project threshold of "
            f"{ELIGIBILITY_THRESHOLD:.0f}."
        )


df["eligibility_reason"] = df.apply(
    eligibility_reason,
    axis=1
)

# ---------------------------------------------------------
# FINAL RESULT TABLE
# ---------------------------------------------------------

final_columns = [
    "image_id",
    "classification_name",
    "classification_confidence",
    "predicted_damage_percentage",
    "severity",
    "assessment_score",
    "assessment_category",
    "insurance_eligibility",
    "eligibility_reason"
]

final_results = df[final_columns].copy()

# ---------------------------------------------------------
# DISPLAY
# ---------------------------------------------------------

print("\nFinal Insurance Assessment:")

print(
    final_results.to_string(
        index=False
    )
)

print("\n" + "-" * 70)

print("Eligibility distribution:")

print(
    final_results[
        "insurance_eligibility"
    ].value_counts()
)

print("\nEligibility percentage:")

eligibility_percentage = (
    final_results[
        "insurance_eligibility"
    ]
    .value_counts(normalize=True)
    * 100
)

print(
    eligibility_percentage.round(2)
)

# ---------------------------------------------------------
# SAVE
# ---------------------------------------------------------

output_path = os.path.join(
    output_dir,
    "final_insurance_assessment.csv"
)

final_results.to_csv(
    output_path,
    index=False
)

print("\nProject-defined threshold:")
print(
    f"Assessment Score >= "
    f"{ELIGIBILITY_THRESHOLD:.0f} "
    f"→ Insurance Eligible"
)

print(
    f"Assessment Score < "
    f"{ELIGIBILITY_THRESHOLD:.0f} "
    f"→ Not Eligible"
)

print("\nSaved to:")
print(output_path)

print("\n" + "=" * 70)
print(
    "✅ PROJECT INSURANCE ELIGIBILITY GENERATED"
)
