# ---------------------------------------------------------
# LOAD CLASS MAPPING
# ---------------------------------------------------------

with open(mapping_path, "r") as f:
    mapping_data = json.load(f)

if "idx_to_class" in mapping_data:

    idx_to_class = {
        int(k): v
        for k, v in mapping_data["idx_to_class"].items()
    }

else:

    idx_to_class = {
        int(v): k
        for k, v in mapping_data["class_to_idx"].items()
    }

print("\nClass mapping:")
