import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import numpy as np

from PIL import Image
from torchvision import models, transforms

print("=" * 70)
print("STEP 70C — EXACT SINGLE IMAGE SEGMENTATION INFERENCE")
print("=" * 70)

# ---------------------------------------------------------
# PATHS
# ---------------------------------------------------------

project_root = "/content/drive/MyDrive/END SEM PROJECT-DL"

model_path = os.path.join(
    project_root,
    "outputs",
    "segmentation_model",
    "best_unet_resnet18.pth"
)

test_image_path = os.path.join(
    project_root,
    "image",
    "841.jpeg"
)

# ---------------------------------------------------------
# DEVICE
# ---------------------------------------------------------

device = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

print(f"Device: {device}")


# ---------------------------------------------------------
# DECODER BLOCK
# EXACT CHECKPOINT STRUCTURE
# ---------------------------------------------------------

class DecoderBlock(nn.Module):

    def __init__(self, in_channels, out_channels):

        super().__init__()

        self.block = nn.Sequential(

            nn.Conv2d(
                in_channels,
                out_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),

            nn.BatchNorm2d(
                out_channels
            ),

            nn.ReLU(
                inplace=True
            ),

            nn.Conv2d(
                out_channels,
                out_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),

            nn.BatchNorm2d(
                out_channels
            ),

            nn.ReLU(
                inplace=True
            )
        )

    def forward(self, x):

        return self.block(x)


# ---------------------------------------------------------
# EXACT U-NET RESNET18 ARCHITECTURE
# ---------------------------------------------------------

class UNetResNet18(nn.Module):

    def __init__(self):

        super().__init__()

        # -------------------------------------------------
        # RESNET18 ENCODER
        # -------------------------------------------------

        encoder = models.resnet18(
            weights=None
        )

        self.enc1 = nn.Sequential(
            encoder.conv1,
            encoder.bn1,
            encoder.relu
        )

        self.pool1 = encoder.maxpool

        self.enc2 = encoder.layer1
        self.enc3 = encoder.layer2
        self.enc4 = encoder.layer3
        self.enc5 = encoder.layer4

        # -------------------------------------------------
        # UPSAMPLING LAYERS
        # -------------------------------------------------

        self.up4 = nn.ConvTranspose2d(
            512,
            256,
            kernel_size=2,
            stride=2
        )

        self.up3 = nn.ConvTranspose2d(
            256,
            128,
            kernel_size=2,
            stride=2
        )

        self.up2 = nn.ConvTranspose2d(
            128,
            64,
            kernel_size=2,
            stride=2
        )

        self.up1 = nn.ConvTranspose2d(
            64,
            64,
            kernel_size=2,
            stride=2
        )

        # -------------------------------------------------
        # DECODER BLOCKS
        # -------------------------------------------------

        self.dec4 = DecoderBlock(
            512,
            256
        )

        self.dec3 = DecoderBlock(
            256,
            128
        )

        self.dec2 = DecoderBlock(
            128,
            64
        )

        self.dec1 = DecoderBlock(
            128,
            64
        )

        # -------------------------------------------------
        # FINAL UPSAMPLING
        # -------------------------------------------------

        self.final_up = nn.ConvTranspose2d(
            64,
            32,
            kernel_size=2,
            stride=2
        )

        self.final_conv = nn.Conv2d(
            32,
            1,
            kernel_size=1
        )

    def forward(self, x):

        # -------------------------------------------------
        # ENCODER
        # -------------------------------------------------

        e1 = self.enc1(x)

        e2 = self.enc2(
            self.pool1(e1)
        )

        e3 = self.enc3(e2)

        e4 = self.enc4(e3)

        e5 = self.enc5(e4)

        # -------------------------------------------------
        # DECODER 4
        # -------------------------------------------------

        d4 = self.up4(e5)

        if d4.shape[-2:] != e4.shape[-2:]:
            d4 = F.interpolate(
                d4,
                size=e4.shape[-2:],
                mode="bilinear",
                align_corners=False
            )

        d4 = torch.cat(
            [d4, e4],
            dim=1
        )

        d4 = self.dec4(d4)

        # -------------------------------------------------
        # DECODER 3
        # -------------------------------------------------

        d3 = self.up3(d4)

        if d3.shape[-2:] != e3.shape[-2:]:
            d3 = F.interpolate(
                d3,
                size=e3.shape[-2:],
                mode="bilinear",
                align_corners=False
            )

        d3 = torch.cat(
            [d3, e3],
            dim=1
        )

        d3 = self.dec3(d3)

        # -------------------------------------------------
        # DECODER 2
        # -------------------------------------------------

        d2 = self.up2(d3)

        if d2.shape[-2:] != e2.shape[-2:]:
            d2 = F.interpolate(
                d2,
                size=e2.shape[-2:],
                mode="bilinear",
                align_corners=False
            )

        d2 = torch.cat(
            [d2, e2],
            dim=1
        )

        d2 = self.dec2(d2)

        # -------------------------------------------------
        # DECODER 1
        # -------------------------------------------------

        d1 = self.up1(d2)

        if d1.shape[-2:] != e1.shape[-2:]:
            d1 = F.interpolate(
                d1,
                size=e1.shape[-2:],
                mode="bilinear",
                align_corners=False
            )

        d1 = torch.cat(
            [d1, e1],
            dim=1
        )

        d1 = self.dec1(d1)

        # -------------------------------------------------
        # FINAL OUTPUT
        # -------------------------------------------------

        out = self.final_up(d1)

        out = self.final_conv(out)

        return out


# ---------------------------------------------------------
# CREATE MODEL
# ---------------------------------------------------------

model = UNetResNet18()

# ---------------------------------------------------------
