# 5. FINAL INFERENCE FUNCTION
# =========================================================

def predict_vehicle_damage(image_path):

    # -----------------------------------------------------
    # LOAD IMAGE
    # -----------------------------------------------------

    image = Image.open(
        image_path
    ).convert("RGB")

    original_size = image.size


    # -----------------------------------------------------
    # CLASSIFICATION
    # -----------------------------------------------------

    classification_input = (
        classification_transform(image)
        .unsqueeze(0)
        .to(device)
    )

    with torch.no_grad():

        classification_logits = classification_model(
            classification_input
        )

        classification_probabilities = torch.softmax(
            classification_logits,
            dim=1
        )

        predicted_label = torch.argmax(
            classification_probabilities,
            dim=1
        ).item()

        classification_confidence = (
            classification_probabilities[
                0,
                predicted_label
            ].item()
        )

    predicted_class = idx_to_class[
        predicted_label
    ]


    # -----------------------------------------------------
    # SEGMENTATION
    # -----------------------------------------------------

    segmentation_input = (
        segmentation_transform(image)
        .unsqueeze(0)
        .to(device)
    )

    with torch.no_grad():

        segmentation_logits = segmentation_model(
            segmentation_input
        )

        segmentation_probability = torch.sigmoid(
            segmentation_logits
        )

        predicted_mask = (
            segmentation_probability >= 0.5
        ).float()


    # -----------------------------------------------------
    # DAMAGE AREA
    # -----------------------------------------------------

    mask = predicted_mask[
        0,
        0
    ].cpu().numpy()

    damage_pixels = int(
        np.sum(mask > 0)
    )

    total_pixels = int(
        mask.size
    )

    damage_percentage = (
        damage_pixels /
        total_pixels
    ) * 100


    # -----------------------------------------------------
    # SEVERITY
    # -----------------------------------------------------

    if damage_percentage == 0:

        severity = "No Damage"
        severity_score = 0

    elif damage_percentage < 5:

        severity = "Low"
        severity_score = 25

    elif damage_percentage < 15:

        severity = "Moderate"
        severity_score = 50

    elif damage_percentage < 30:

        severity = "High"
        severity_score = 75

    else:

        severity = "Very High"
        severity_score = 100


    # -----------------------------------------------------
    # ASSESSMENT SCORE
    # -----------------------------------------------------

    damage_score = min(
        damage_percentage,
        100
    )

    confidence_score = (
        classification_confidence * 100
    )

    assessment_score = (
        0.60 * damage_score
        +
        0.40 * confidence_score
    )


    # -----------------------------------------------------
    # ASSESSMENT CATEGORY
    # -----------------------------------------------------

    if assessment_score < 25:

        assessment_category = "Low Assessment"

    elif assessment_score < 50:

        assessment_category = "Moderate Assessment"

    elif assessment_score < 75:

        assessment_category = "High Assessment"

    else:

        assessment_category = "Very High Assessment"


    # -----------------------------------------------------
    # PROJECT-DEFINED INSURANCE ELIGIBILITY
    # -----------------------------------------------------

    if assessment_score >= 25:

        insurance_status = "Insurance Eligible"

    else:

        insurance_status = "Not Eligible"


    # -----------------------------------------------------
    # RETURN RESULTS
    # -----------------------------------------------------

    return {

        "image_path": image_path,

        "image_size": original_size,

        "damage_type": predicted_class,

        "classification_confidence":
            classification_confidence * 100,

        "damage_pixels":
            damage_pixels,

        "damage_percentage":
            damage_percentage,

        "severity":
            severity,

        "severity_score":
            severity_score,

        "assessment_score":
            assessment_score,

        "assessment_category":
            assessment_category,

        "insurance_status":
            insurance_status
    }


