# =========================================================
# STEP 77 — CORRECTED DAMAGE ASSESSMENT LOGIC
# =========================================================

def corrected_assessment(damage_percentage):

    # -----------------------------------------------------
    # SMALL SEGMENTATION NOISE / NO SIGNIFICANT DAMAGE
    # -----------------------------------------------------
    # Project-defined threshold.
    # Very small predicted areas are treated as
    # insignificant damage / segmentation noise.

    if damage_percentage < 2.5:

        severity = "No Significant Damage"
        severity_score = 0
        assessment_score = 0

    # -----------------------------------------------------
    # LOW DAMAGE
    # -----------------------------------------------------

    elif damage_percentage < 5:

        severity = "Low"
        severity_score = 25
        assessment_score = 25

    # -----------------------------------------------------
    # MODERATE DAMAGE
    # -----------------------------------------------------

    elif damage_percentage < 15:

        severity = "Moderate"
        severity_score = 50
        assessment_score = 50

    # -----------------------------------------------------
    # HIGH DAMAGE
    # -----------------------------------------------------

    elif damage_percentage < 30:

        severity = "High"
        severity_score = 75
        assessment_score = 75

    # -----------------------------------------------------
    # VERY HIGH DAMAGE
    # -----------------------------------------------------

    else:

        severity = "Very High"
        severity_score = 100
        assessment_score = 100

    # -----------------------------------------------------
    # PROJECT-DEFINED ELIGIBILITY
    # -----------------------------------------------------

    if assessment_score >= 25:

        insurance_status = "Insurance Eligible"

    else:

        insurance_status = "Not Eligible"

    return {
        "severity": severity,
        "severity_score": severity_score,
        "assessment_score": assessment_score,
        "insurance_status": insurance_status
    }


