# =========================================================
# STEP 78 — UPDATE MAIN INFERENCE PIPELINE
# =========================================================

def predict_vehicle_damage(image_path):

    # =====================================================
    # LOAD IMAGE
    # =====================================================

    image = Image.open(image_path).convert("RGB")

    # =====================================================
    # 1. CLASSIFICATION
    # =====================================================

    classification_tensor = (
        classification_transform(image)
        .unsqueeze(0)
        .to(device)
    )

    classification_model.eval()

    with torch.no_grad():

        classification_output = (
            classification_model(classification_tensor)
        )

        classification_probabilities = torch.softmax(
            classification_output,
            dim=1
        )

        predicted_class_index = (
            torch.argmax(
                classification_probabilities,
                dim=1
            ).item()
        )

        classification_confidence = (
            classification_probabilities[
                0,
                predicted_class_index
            ].item() * 100
        )

    classification_name = class_mapping[
        predicted_class_index
    ]

    # =====================================================
    # 2. SEGMENTATION
    # =====================================================

    segmentation_tensor = (
        segmentation_transform(image)
        .unsqueeze(0)
        .to(device)
    )

    segmentation_model.eval()

    with torch.no_grad():

        segmentation_output = (
            segmentation_model(segmentation_tensor)
        )

        segmentation_probability = torch.sigmoid(
            segmentation_output
        )

        predicted_mask = (
            segmentation_probability > 0.5
        ).float()

    # =====================================================
    # 3. DAMAGE AREA
    # =====================================================

    damage_pixels = int(
        predicted_mask.sum().item()
    )

    total_pixels = (
        predicted_mask.shape[-1]
        * predicted_mask.shape[-2]
    )

    damage_percentage = (
        damage_pixels / total_pixels
    ) * 100

    # =====================================================
    # 4. CORRECTED DAMAGE ASSESSMENT
    # =====================================================

    # Project-defined threshold:
    # Areas below 2.5% are treated as
    # no significant damage / segmentation noise.

    if damage_percentage < 2.5:

        severity = "No Significant Damage"
        severity_score = 0
        assessment_score = 0

    elif damage_percentage < 5:

        severity = "Low"
        severity_score = 25
        assessment_score = 25

    elif damage_percentage < 15:

        severity = "Moderate"
        severity_score = 50
        assessment_score = 50

    elif damage_percentage < 30:

        severity = "High"
        severity_score = 75
        assessment_score = 75

    else:

        severity = "Very High"
        severity_score = 100
        assessment_score = 100

    # =====================================================
    # 5. PROJECT-DEFINED ELIGIBILITY
    # =====================================================

    if assessment_score >= 25:

        insurance_status = "Insurance Eligible"

    else:

        insurance_status = "Not Eligible"

    # =====================================================
    # 6. RETURN COMPLETE RESULT
    # =====================================================

    return {

        "image": os.path.basename(image_path),

        "image_size": image.size,

        "damage_type": classification_name,

        "classification_confidence":
            classification_confidence,

        "damage_pixels":
            damage_pixels,

        "damage_percentage":
            damage_percentage,

        "severity":
            severity,

        "severity_score":
            severity_score,

        "assessment_score":
            assessment_score,

        "assessment_category":
            (
                "No Significant Damage"
                if assessment_score == 0
                else
                "Low Assessment"
                if assessment_score < 25
                else
                "Moderate Assessment"
                if assessment_score < 50
                else
                "High Assessment"
                if assessment_score < 75
                else
                "Very High Assessment"
            ),

        "insurance_status":
            insurance_status
    }


print("=" * 70)
print("STEP 78 — MAIN INFERENCE PIPELINE UPDATED")
print("=" * 70)

print("\nClassification model : Unchanged")
print("Segmentation model   : Unchanged")
print("Damage scoring       : Updated")
print("Confidence weighting  : Removed")
print("Small-area threshold  : 2.5%")
print("Eligibility threshold : Score >= 25")
