import torch
import torch.nn as nn
import pandas as pd
import numpy as np
from PIL import Image
from torchvision import models, transforms
from torch.utils.data import DataLoader, Dataset

# ------------------------------------------------------------
# 1. Paths
# ------------------------------------------------------------

PROJECT_DIR = "/content/drive/MyDrive/END SEM PROJECT-DL"

TEST_CSV = (
    f"{PROJECT_DIR}/outputs/segmentation_dataset/"
    "splits/test.csv"
)

CHECKPOINT = (
    f"{PROJECT_DIR}/outputs/segmentation_model/"
    "best_unet_resnet18.pth"
)

# ------------------------------------------------------------
# 2. Device
# ------------------------------------------------------------

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

print("Device:", device)

# ------------------------------------------------------------
# 3. Load test dataframe
# ------------------------------------------------------------

test_df = pd.read_csv(TEST_CSV)

print("Test images:", len(test_df))

# ------------------------------------------------------------
# 4. Dataset
# ------------------------------------------------------------

class SegmentationTestDataset(Dataset):

    def __init__(self, dataframe):
        self.df = dataframe.reset_index(drop=True)

        self.transform = transforms.Compose([
            transforms.Resize((256, 256)),
            transforms.ToTensor(),
            transforms.Normalize(
                mean=[0.485, 0.456, 0.406],
                std=[0.229, 0.224, 0.225]
            )
        ])

    def __len__(self):
        return len(self.df)

    def __getitem__(self, idx):

        row = self.df.iloc[idx]

        image = Image.open(row["image"]).convert("RGB")
        mask = Image.open(row["mask"]).convert("L")

        image = self.transform(image)

        mask = mask.resize((256, 256), Image.NEAREST)
        mask = np.array(mask)

        mask = (mask > 0).astype(np.float32)
        mask = torch.tensor(mask).unsqueeze(0)

        return image, mask


test_dataset = SegmentationTestDataset(test_df)

test_loader = DataLoader(
    test_dataset,
    batch_size=16,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

# ------------------------------------------------------------
# 5. EXACT U-NET RESNET18 ARCHITECTURE
# ------------------------------------------------------------

class DoubleConv(nn.Module):

    def __init__(self, in_channels, out_channels):

        super().__init__()

        self.block = nn.Sequential(

            nn.Conv2d(
                in_channels,
                out_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),

            nn.BatchNorm2d(out_channels),
            nn.ReLU(inplace=True),

            nn.Conv2d(
                out_channels,
                out_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),

            nn.BatchNorm2d(out_channels),
            nn.ReLU(inplace=True)
        )

    def forward(self, x):
        return self.block(x)


class UNetResNet18(nn.Module):

    def __init__(self):

        super().__init__()

        resnet = models.resnet18(weights=None)

        self.enc1 = nn.Sequential(
            resnet.conv1,
            resnet.bn1,
            resnet.relu
        )

        self.pool1 = resnet.maxpool

        self.enc2 = resnet.layer1
        self.enc3 = resnet.layer2
        self.enc4 = resnet.layer3
        self.enc5 = resnet.layer4

        self.up4 = nn.ConvTranspose2d(
            512, 256, kernel_size=2, stride=2
        )

        self.dec4 = DoubleConv(512, 256)

        self.up3 = nn.ConvTranspose2d(
            256, 128, kernel_size=2, stride=2
        )

        self.dec3 = DoubleConv(256, 128)

        self.up2 = nn.ConvTranspose2d(
            128, 64, kernel_size=2, stride=2
        )

        self.dec2 = DoubleConv(128, 64)

        self.up1 = nn.ConvTranspose2d(
            64, 64, kernel_size=2, stride=2
        )

        self.dec1 = DoubleConv(128, 64)

        self.final_up = nn.ConvTranspose2d(
            64, 32, kernel_size=2, stride=2
        )

        self.final_conv = nn.Conv2d(
            32, 1, kernel_size=1
        )

    def forward(self, x):

        e1 = self.enc1(x)
        e2 = self.enc2(self.pool1(e1))
        e3 = self.enc3(e2)
        e4 = self.enc4(e3)
        e5 = self.enc5(e4)

        d4 = self.up4(e5)
        d4 = torch.cat([d4, e4], dim=1)
        d4 = self.dec4(d4)

        d3 = self.up3(d4)
        d3 = torch.cat([d3, e3], dim=1)
        d3 = self.dec3(d3)

        d2 = self.up2(d3)
        d2 = torch.cat([d2, e2], dim=1)
        d2 = self.dec2(d2)

        d1 = self.up1(d2)
        d1 = torch.cat([d1, e1], dim=1)
        d1 = self.dec1(d1)

        out = self.final_up(d1)
        out = self.final_conv(out)

        return out


# ------------------------------------------------------------
# 6. Load model
# ------------------------------------------------------------

model = UNetResNet18().to(device)

checkpoint = torch.load(
    CHECKPOINT,
    map_location=device
)

model.load_state_dict(
    checkpoint["model_state_dict"]
)

model.eval()

print("U-Net ResNet18 loaded successfully")

# ------------------------------------------------------------
# 7. Generate probability maps
# ------------------------------------------------------------

all_probabilities = []
all_masks = []

with torch.no_grad():

    for images, masks in test_loader:

        images = images.to(device)

        logits = model(images)

        probabilities = torch.sigmoid(logits)

        all_probabilities.append(
            probabilities.cpu()
        )

        all_masks.append(
            masks.cpu()
        )


all_probabilities = torch.cat(
    all_probabilities,
    dim=0
)

all_masks = torch.cat(
    all_masks,
    dim=0
)

print(
    "Probability tensor:",
    tuple(all_probabilities.shape)
)

print(
    "Ground-truth tensor:",
    tuple(all_masks.shape)
)

# ------------------------------------------------------------
# 8. Evaluate multiple thresholds
# ------------------------------------------------------------

thresholds = [0.30, 0.40, 0.50, 0.60, 0.70]

results = []

for threshold in thresholds:

    predictions = (
        all_probabilities >= threshold
    ).float()

    intersection = (
        predictions * all_masks
    ).sum(dim=(1,2,3))

    pred_area = predictions.sum(dim=(1,2,3))
    true_area = all_masks.sum(dim=(1,2,3))

    dice = (
        (2 * intersection + 1e-7) /
        (pred_area + true_area + 1e-7)
    )

    union = (
        pred_area +
        true_area -
        intersection
    )

    iou = (
        (intersection + 1e-7) /
        (union + 1e-7)
    )

    precision = (
        (intersection + 1e-7) /
        (pred_area + 1e-7)
    )

    recall = (
        (intersection + 1e-7) /
        (true_area + 1e-7)
    )

    pred_percentage = (
        pred_area / (256 * 256)
    ) * 100

    true_percentage = (
        true_area / (256 * 256)
    ) * 100

    area_mae = torch.abs(
        pred_percentage -
        true_percentage
    ).mean()

    results.append({
        "threshold": threshold,
        "dice": dice.mean().item(),
        "iou": iou.mean().item(),
        "precision": precision.mean().item(),
        "recall": recall.mean().item(),
        "area_MAE": area_mae.item(),
        "avg_predicted_area": pred_percentage.mean().item()
    })


results_df = pd.DataFrame(results)

print("\n==============================================")
print("SEGMENTATION THRESHOLD CALIBRATION RESULTS")
print("==============================================")

print(
    results_df.round(4).to_string(index=False)
)

# ------------------------------------------------------------
# 9. Select best threshold by Dice
# ------------------------------------------------------------

best_row = results_df.loc[
    results_df["dice"].idxmax()
]

best_threshold = best_row["threshold"]

print("\n==============================================")
print("BEST THRESHOLD")
print("==============================================")

print(
    "Best threshold:",
    best_threshold
)

print(
    "Dice:",
    round(best_row["dice"], 4)
)

print(
    "IoU:",
    round(best_row["iou"], 4)
)

print(
    "Precision:",
    round(best_row["precision"], 4)
)

print(
    "Recall:",
    round(best_row["recall"], 4)
)

print(
    "Area MAE:",
    round(best_row["area_MAE"], 4),
    "%"
)

print("\nSTEP 82 COMPLETE")

