# STEP 83C — CLEAN vs DAMAGED PROBABILITY ANALYSIS
# ============================================================

import torch
import numpy as np
import pandas as pd
from PIL import Image
from torchvision import transforms

# ------------------------------------------------------------
# 1. Paths
# ------------------------------------------------------------

CLEAN_IMAGE = "/tmp/uploaded_clean_car_image.jpg"
DAMAGED_IMAGE = "/tmp/uploaded_car_image.jpg"

# ------------------------------------------------------------
# 2. Device
# ------------------------------------------------------------

device = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

print("Device:", device)

# ------------------------------------------------------------
# 3. Segmentation transform
# ------------------------------------------------------------

seg_transform = transforms.Compose([
    transforms.Resize((256, 256)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

# ------------------------------------------------------------
# 4. Make sure the U-Net model exists
# ------------------------------------------------------------

model = model.to(device)
model.eval()

print("Segmentation model ready")

# ------------------------------------------------------------
# 5. Get probability map
# ------------------------------------------------------------

def get_probability_map(image_path):

    image = Image.open(image_path).convert("RGB")

    original_size = image.size

    image_tensor = seg_transform(
        image
    ).unsqueeze(0).to(device)

    with torch.no_grad():

        logits = model(image_tensor)

        probabilities = torch.sigmoid(logits)

    probability_map = (
        probabilities[0, 0]
        .cpu()
        .numpy()
    )

    return probability_map, original_size


# ------------------------------------------------------------
# 6. Generate probability maps
# ------------------------------------------------------------

clean_prob, clean_size = get_probability_map(
    CLEAN_IMAGE
)

damaged_prob, damaged_size = get_probability_map(
    DAMAGED_IMAGE
)

print("\nClean image size:", clean_size)
print("Damaged image size:", damaged_size)

# ------------------------------------------------------------
# 7. Threshold comparison
# ------------------------------------------------------------

thresholds = [
    0.10,
    0.20,
    0.30,
    0.40,
    0.50,
    0.60,
    0.70,
    0.80,
    0.90
]

results = []

total_pixels = 256 * 256

for threshold in thresholds:

    clean_pixels = (
        clean_prob >= threshold
    ).sum()

    damaged_pixels = (
        damaged_prob >= threshold
    ).sum()

    clean_area = (
        clean_pixels / total_pixels
    ) * 100

    damaged_area = (
        damaged_pixels / total_pixels
    ) * 100

    results.append({
        "threshold": threshold,
        "clean_area_%": clean_area,
        "damaged_area_%": damaged_area,
        "difference_%": damaged_area - clean_area
    })


results_df = pd.DataFrame(results)

print("\n==============================================")
print("CLEAN vs DAMAGED")
print("==============================================")

print(
    results_df.round(4).to_string(index=False)
)

# ------------------------------------------------------------
# 8. Probability statistics
# ------------------------------------------------------------

print("\n==============================================")
print("PROBABILITY STATISTICS")
print("==============================================")

print("\nCLEAN IMAGE")

print(
    "Maximum probability:",
    round(float(clean_prob.max()), 4)
)

print(
    "Mean probability:",
    round(float(clean_prob.mean()), 4)
)

print(
    "Pixels >= 0.5:",
    int((clean_prob >= 0.5).sum())
)

print("\nDAMAGED IMAGE")

print(
    "Maximum probability:",
    round(float(damaged_prob.max()), 4)
)

print(
    "Mean probability:",
    round(float(damaged_prob.mean()), 4)
)

print(
    "Pixels >= 0.5:",
    int((damaged_prob >= 0.5).sum())
)

print(
    "Pixels >= 0.1:",
    int((damaged_prob >= 0.1).sum())
)

# ------------------------------------------------------------
# 9. Probability percentiles
# ------------------------------------------------------------

print("\n==============================================")
print("PROBABILITY PERCENTILES")
print("==============================================")

percentiles = [
    50,
    75,
    90,
    95,
    99,
    99.5,
    99.9
]

print("\nClean:")

for p in percentiles:

    print(
        f"{p}%:",
        round(
            float(
                np.percentile(clean_prob, p)
            ),
            4
        )
    )

print("\nDamaged:")

for p in percentiles:

    print(
        f"{p}%:",
        round(
            float(
                np.percentile(damaged_prob, p)
            ),
            4
        )
    )

print("\nSTEP 83C COMPLETE")

