# STEP 84 — CLEAN vs DAMAGED CLASSIFICATION TEST
# ============================================================

import torch
import numpy as np
from PIL import Image
from torchvision import transforms

# ------------------------------------------------------------
# Paths
# ------------------------------------------------------------

CLEAN_IMAGE = "/tmp/uploaded_clean_car_image.jpg"
DAMAGED_IMAGE = "/tmp/uploaded_car_image.jpg"

# ------------------------------------------------------------
# Device
# ------------------------------------------------------------

device = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

print("Device:", device)

# ------------------------------------------------------------
# Classification transform
# ------------------------------------------------------------

class_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

# ------------------------------------------------------------
# Class mapping
# ------------------------------------------------------------

class_names = {
    0: "bumper_dent",
    1: "bumper_scratch",
    2: "door_dent",
    3: "door_scratch",
    4: "glass_shatter",
    5: "head_lamp",
    6: "tail_lamp",
    7: "unknown"
}

# ------------------------------------------------------------
# Make sure EfficientNet exists
# ------------------------------------------------------------

classification_model = classification_model.to(device)
classification_model.eval()

print("EfficientNet-B0 ready")

# ------------------------------------------------------------
# Prediction function
# ------------------------------------------------------------

def classify_external_image(image_path):

    image = Image.open(
        image_path
    ).convert("RGB")

    tensor = class_transform(
        image
    ).unsqueeze(0).to(device)

    with torch.no_grad():

        logits = classification_model(
            tensor
        )

        probabilities = torch.softmax(
            logits,
            dim=1
        )[0]

    top_values, top_indices = torch.topk(
        probabilities,
        k=8
    )

    results = []

    for probability, index in zip(
        top_values.cpu().numpy(),
        top_indices.cpu().numpy()
    ):

        results.append({
            "class": class_names[int(index)],
            "confidence_%": float(probability * 100)
        })

    return results


# ------------------------------------------------------------
# Clean image
# ------------------------------------------------------------

clean_results = classify_external_image(
    CLEAN_IMAGE
)

print("\n==============================================")
print("CLEAN CAR — CLASSIFICATION")
print("==============================================")

for item in clean_results:

    print(
        f"{item['class']:20s} "
        f"{item['confidence_%']:.2f}%"
    )


# ------------------------------------------------------------
# Damaged image
# ------------------------------------------------------------

damaged_results = classify_external_image(
    DAMAGED_IMAGE
)

print("\n==============================================")
print("DAMAGED CAR — CLASSIFICATION")
print("==============================================")

for item in damaged_results:

    print(
        f"{item['class']:20s} "
        f"{item['confidence_%']:.2f}%"
    )


# ------------------------------------------------------------
# Final comparison
# ------------------------------------------------------------

clean_top = clean_results[0]
damaged_top = damaged_results[0]

print("\n==============================================")
print("TOP PREDICTION COMPARISON")
print("==============================================")

print(
    "Clean car:",
    clean_top["class"],
    f"({clean_top['confidence_%']:.2f}%)"
)

print(
    "Damaged car:",
    damaged_top["class"],
    f"({damaged_top['confidence_%']:.2f}%)"
)

print("\nSTEP 84 COMPLETE")

