import os
import pandas as pd
import matplotlib.pyplot as plt
from PIL import Image

PROJECT_DIR = "/content/drive/MyDrive/END SEM PROJECT-DL"

CSV_PATH = (
    f"{PROJECT_DIR}/outputs/classification_dataset/"
    "classification_labels.csv"
)

IMAGE_DIR = f"{PROJECT_DIR}/image"
OUTPUT_DIR = f"{PROJECT_DIR}/outputs/visual_inspection"

os.makedirs(OUTPUT_DIR, exist_ok=True)

df = pd.read_csv(CSV_PATH)

# ------------------------------------------------------------
# Select samples
# ------------------------------------------------------------

unknown_df = (
    df[df["classes"] == "unknown"]
    .sample(n=8, random_state=42)
    .reset_index(drop=True)
)

damage_df = (
    df[df["classes"] != "unknown"]
    .sample(n=8, random_state=42)
    .reset_index(drop=True)
)

# ------------------------------------------------------------
# Function to create grid
# ------------------------------------------------------------

def create_grid(dataframe, title, output_path):

    fig, axes = plt.subplots(
        2, 4,
        figsize=(16, 9)
    )

    axes = axes.flatten()

    print("\n" + title)
    print("-" * 60)

    for i, row in dataframe.iterrows():

        image_name = os.path.basename(
            row["image"]
        )

        image_path = os.path.join(
            IMAGE_DIR,
            image_name
        )

        image = Image.open(
            image_path
        ).convert("RGB")

        axes[i].imshow(image)

        axes[i].set_title(
            f"{image_name}\n{row['classes']}",
            fontsize=10
        )

        axes[i].axis("off")

        print(
            f"{i+1}. {image_name} → {row['classes']}"
        )

    plt.suptitle(
        title,
        fontsize=16,
        fontweight="bold"
    )

    plt.tight_layout()

    plt.savefig(
        output_path,
        dpi=150,
        bbox_inches="tight"
    )

    plt.show()

    plt.close()


# ------------------------------------------------------------
# Create UNKNOWN grid
# ------------------------------------------------------------

unknown_output = os.path.join(
    OUTPUT_DIR,
    "unknown_samples.png"
)

create_grid(
    unknown_df,
    "UNKNOWN CLASS SAMPLES",
    unknown_output
)

# ------------------------------------------------------------
# Create DAMAGE grid
# ------------------------------------------------------------

damage_output = os.path.join(
    OUTPUT_DIR,
    "damage_samples.png"
)

create_grid(
    damage_df,
    "DAMAGE CLASS SAMPLES",
    damage_output
)

print("\n==============================================")
print("FILES SAVED")
print("==============================================")

print(
    "Unknown samples:",
    unknown_output
)

print(
    "Damage samples:",
    damage_output
)

print("\nSTEP 86A COMPLETE")

# ============================================================
# STEP 86B — UNKNOWN CLASS ANALYSIS
# ============================================================

import os
import pandas as pd
from PIL import Image
import numpy as np

PROJECT_DIR = "/content/drive/MyDrive/END SEM PROJECT-DL"

CSV_PATH = (
    f"{PROJECT_DIR}/outputs/classification_dataset/"
    "classification_labels.csv"
)

IMAGE_DIR = f"{PROJECT_DIR}/image"

df = pd.read_csv(CSV_PATH)

unknown_df = df[df["classes"] == "unknown"].copy()

print("==============================================")
print("UNKNOWN CLASS ANALYSIS")
print("==============================================")

print("Total unknown images:", len(unknown_df))

# ------------------------------------------------------------
# Check image readability and dimensions
# ------------------------------------------------------------

valid = 0
unreadable = 0
dimensions = []

for _, row in unknown_df.iterrows():

    image_name = os.path.basename(row["image"])
    image_path = os.path.join(IMAGE_DIR, image_name)

    try:
        img = Image.open(image_path)
        img.verify()

        img = Image.open(image_path)
        dimensions.append(img.size)

        valid += 1

    except Exception:
        unreadable += 1


print("Readable images:", valid)
print("Unreadable images:", unreadable)

# ------------------------------------------------------------
# Dimension statistics
# ------------------------------------------------------------

if dimensions:

    widths = [x[0] for x in dimensions]
    heights = [x[1] for x in dimensions]

    print("\nImage dimension statistics:")
    print("Minimum width :", min(widths))
    print("Maximum width :", max(widths))
    print("Minimum height:", min(heights))
    print("Maximum height:", max(heights))

# ------------------------------------------------------------
# Compare unknown vs damage class counts
# ------------------------------------------------------------

print("\n==============================================")
print("CLASS DISTRIBUTION")
print("==============================================")

class_counts = df["classes"].value_counts()

print(class_counts.to_string())

print("\n==============================================")
print("INTERPRETATION")
print("==============================================")

print(
    "The 'unknown' class contains",
    len(unknown_df),
    "images."
)

print(
    "We will NOT automatically assume that 'unknown' means "
    "'no damage'."
)

print(
    "The next step is to inspect whether these images are "
    "visually clean/no-damage images before using them as "
    "negative samples."
)

print("\nSTEP 86B COMPLETE")

