# ============================================================
# STEP 86D — CHECK UNKNOWN IMAGES AGAINST DAMAGE ANNOTATIONS
# ============================================================

import os
import pandas as pd
import json

PROJECT_DIR = "/content/drive/MyDrive/END SEM PROJECT-DL"

CLASSIFICATION_CSV = (
    f"{PROJECT_DIR}/outputs/classification_dataset/"
    "classification_labels.csv"
)

ANN_DIR = (
    f"{PROJECT_DIR}/outputs/clean_car_parts/ann"
)

df = pd.read_csv(CLASSIFICATION_CSV)

unknown_df = df[df["classes"] == "unknown"].copy()

print("==============================================")
print("UNKNOWN vs SEGMENTATION ANNOTATIONS")
print("==============================================")

unknown_count = len(unknown_df)

with_annotation = 0
without_annotation = 0
objects_found = 0

examples_with_damage = []
examples_without_damage = []

for _, row in unknown_df.iterrows():

    image_name = os.path.basename(row["image"])

    # Annotation filenames were created from the original image name
    ann_path = os.path.join(
        ANN_DIR,
        image_name + ".json"
    )

    if os.path.exists(ann_path):

        with_annotation += 1

        try:
            with open(ann_path, "r") as f:
                ann = json.load(f)

            objects = ann.get("objects", [])

            if len(objects) > 0:
                objects_found += len(objects)

                if len(examples_with_damage) < 10:
                    examples_with_damage.append(
                        (image_name, len(objects))
                    )

            else:
                if len(examples_without_damage) < 10:
                    examples_without_damage.append(
                        image_name
                    )

        except Exception:
            pass

    else:

        without_annotation += 1

# ------------------------------------------------------------
# Results
# ------------------------------------------------------------

print("\nTotal UNKNOWN images:", unknown_count)

print(
    "UNKNOWN images with damage annotations:",
    with_annotation
)

print(
    "UNKNOWN images without annotations:",
    without_annotation
)

print(
    "Total annotated objects among UNKNOWN:",
    objects_found
)

if unknown_count > 0:
    print(
        "Percentage with annotations:",
        round(with_annotation / unknown_count * 100, 2),
        "%"
    )

print("\n==============================================")
print("EXAMPLES WITH ANNOTATIONS")
print("==============================================")

if examples_with_damage:

    for name, count in examples_with_damage:
        print(
            f"{name} → {count} annotated objects"
        )

else:
    print("No annotated UNKNOWN images found.")

print("\n==============================================")
print("EXAMPLES WITHOUT ANNOTATIONS")
print("==============================================")

if examples_without_damage:

    for name in examples_without_damage:
        print(name)

else:
    print("No examples found.")

print("\n==============================================")
print("STEP 86D COMPLETE")
print("==============================================")

