# ============================================================
# STEP 89 — BINARY DATASET AND DATALOADERS
# ============================================================

import os
import pandas as pd
import torch

from PIL import Image
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms

PROJECT_DIR = "/content/drive/MyDrive/END SEM PROJECT-DL"

SPLIT_DIR = (
    f"{PROJECT_DIR}/outputs/binary_classification_dataset/"
    "splits"
)

IMAGE_DIR = f"{PROJECT_DIR}/image"

# ------------------------------------------------------------
# Device
# ------------------------------------------------------------

device = torch.device(
    "cuda" if torch.cuda.is_available() else "cpu"
)

print("==============================================")
print("BINARY DATASET PIPELINE")
print("==============================================")

print("Device:", device)

if torch.cuda.is_available():
    print(
        "GPU:",
        torch.cuda.get_device_name(0)
    )

# ------------------------------------------------------------
# Load split CSVs
# ------------------------------------------------------------

train_df = pd.read_csv(
    os.path.join(SPLIT_DIR, "train.csv")
)

val_df = pd.read_csv(
    os.path.join(SPLIT_DIR, "validation.csv")
)

test_df = pd.read_csv(
    os.path.join(SPLIT_DIR, "test.csv")
)

# ------------------------------------------------------------
# Image transforms
# ------------------------------------------------------------

train_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.RandomHorizontalFlip(p=0.5),
    transforms.RandomRotation(10),
    transforms.ColorJitter(
        brightness=0.15,
        contrast=0.15,
        saturation=0.15
    ),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

eval_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

# ------------------------------------------------------------
# Dataset class
# ------------------------------------------------------------

class BinaryDamageDataset(Dataset):

    def __init__(
        self,
        dataframe,
        image_dir,
        transform=None
    ):

        self.df = dataframe.reset_index(drop=True)
        self.image_dir = image_dir
        self.transform = transform

    def __len__(self):
        return len(self.df)

    def __getitem__(self, idx):

        row = self.df.iloc[idx]

        image_name = os.path.basename(
            row["image"]
        )

        image_path = os.path.join(
            self.image_dir,
            image_name
        )

        image = Image.open(
            image_path
        ).convert("RGB")

        label = int(
            row["binary_class"]
        )

        if self.transform:
            image = self.transform(image)

        return image, label


# ------------------------------------------------------------
# Create datasets
# ------------------------------------------------------------

train_dataset = BinaryDamageDataset(
    train_df,
    IMAGE_DIR,
    train_transform
)

val_dataset = BinaryDamageDataset(
    val_df,
    IMAGE_DIR,
    eval_transform
)

test_dataset = BinaryDamageDataset(
    test_df,
    IMAGE_DIR,
    eval_transform
)

# ------------------------------------------------------------
# Create DataLoaders
# ------------------------------------------------------------

BATCH_SIZE = 32

train_loader = DataLoader(
    train_dataset,
    batch_size=BATCH_SIZE,
    shuffle=True,
    num_workers=2,
    pin_memory=True
)

val_loader = DataLoader(
    val_dataset,
    batch_size=BATCH_SIZE,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

test_loader = DataLoader(
    test_dataset,
    batch_size=BATCH_SIZE,
    shuffle=False,
    num_workers=2,
    pin_memory=True
)

# ------------------------------------------------------------
# Test one batch
# ------------------------------------------------------------

images, labels = next(
    iter(train_loader)
)

print("\n==============================================")
print("BATCH VERIFICATION")
print("==============================================")

print(
    "Image batch shape:",
    images.shape
)

print(
    "Label batch shape:",
    labels.shape
)

print(
    "Image dtype:",
    images.dtype
)

print(
    "Label dtype:",
    labels.dtype
)

print(
    "Labels present:",
    sorted(
        labels.unique().tolist()
    )
)

print("\n==============================================")
print("DATASET SIZES")
print("==============================================")

print("Training:", len(train_dataset))
print("Validation:", len(val_dataset))
print("Testing:", len(test_dataset))

print("\n==============================================")
print("STEP 89 COMPLETE")
print("==============================================")

# ============================================================
# STEP 90 — BINARY EFFICIENTNET-B0 MODEL
# ============================================================

import torch
