# ============================================================
# STEP 91 — BINARY CLASS WEIGHTS
# ============================================================

import torch
import torch.nn as nn

print("==============================================")
print("BINARY CLASS WEIGHTS")
print("==============================================")

# ------------------------------------------------------------
# Count training samples
# ------------------------------------------------------------

class_counts = (
    train_df["binary_class"]
    .value_counts()
    .sort_index()
)

print("Training class counts:")

for label, count in class_counts.items():

    name = {
        0: "No Damage",
        1: "Damage"
    }[label]

    print(
        f"  {label} ({name}): {count}"
    )

# ------------------------------------------------------------
# Calculate balanced weights
# ------------------------------------------------------------

total_samples = len(train_df)
num_classes = 2

class_weights = (
    total_samples /
    (num_classes * class_counts.values)
)

class_weights = torch.tensor(
    class_weights,
    dtype=torch.float32
).to(device)

# ------------------------------------------------------------
# Display weights
# ------------------------------------------------------------

print("\nCalculated class weights:")

print(
    "  0 (No Damage):",
    round(class_weights[0].item(), 4)
)

print(
    "  1 (Damage):",
    round(class_weights[1].item(), 4)
)

# ------------------------------------------------------------
# Create weighted loss
# ------------------------------------------------------------

binary_criterion = nn.CrossEntropyLoss(
    weight=class_weights
)

print("\n==============================================")
print("LOSS FUNCTION")
print("==============================================")

print(binary_criterion)

print("\n==============================================")
print("STEP 91 COMPLETE")
print("==============================================")

# ============================================================
# STEP 92 — BINARY MODEL TRAINING CONFIGURATION
# ============================================================

import torch.optim as optim

print("==============================================")
print("BINARY MODEL TRAINING CONFIGURATION")
print("==============================================")

# ------------------------------------------------------------
# Optimizer
# ------------------------------------------------------------

binary_optimizer = optim.AdamW(
    binary_model.parameters(),
    lr=1e-4,
    weight_decay=1e-4
)

# ------------------------------------------------------------
# Learning-rate scheduler
# ------------------------------------------------------------

binary_scheduler = optim.lr_scheduler.ReduceLROnPlateau(
    binary_optimizer,
    mode="min",
    factor=0.5,
    patience=2
)

# ------------------------------------------------------------
# Training settings
# ------------------------------------------------------------

NUM_EPOCHS = 10

print("Optimizer:")
print("  AdamW")

print("\nLearning rate:")
print(" ", binary_optimizer.param_groups[0]["lr"])

print("\nWeight decay:")
print(" ", binary_optimizer.param_groups[0]["weight_decay"])

print("\nScheduler:")
print("  ReduceLROnPlateau")

print("\nScheduler factor:")
print("  0.5")

print("\nScheduler patience:")
print("  2 epochs")

print("\nNumber of epochs:")
print(" ", NUM_EPOCHS)

print("\nLoss:")
print("  Weighted CrossEntropyLoss")

print("\n==============================================")
print("STEP 92 COMPLETE")
print("==============================================")

# ============================================================
# STEP 93 — TRAIN BINARY DAMAGE DETECTOR
# ============================================================

import os
import time
import numpy as np
import torch

from sklearn.metrics import accuracy_score

MODEL_DIR = (
    f"{PROJECT_DIR}/outputs/binary_classification_model"
)

os.makedirs(MODEL_DIR, exist_ok=True)

BEST_MODEL_PATH = os.path.join(
    MODEL_DIR,
    "best_binary_efficientnet_b0.pth"
)

# ------------------------------------------------------------
# Training history
# ------------------------------------------------------------

history = {
    "train_loss": [],
    "train_accuracy": [],
    "val_loss": [],
    "val_accuracy": []
}

best_val_loss = float("inf")

print("==============================================")
print("BINARY DAMAGE DETECTOR TRAINING")
print("==============================================")

print("Training samples:", len(train_dataset))
print("Validation samples:", len(val_dataset))
print("Batch size:", BATCH_SIZE)
print("Epochs:", NUM_EPOCHS)
print("Device:", device)

# ------------------------------------------------------------
# Training loop
# ------------------------------------------------------------

for epoch in range(NUM_EPOCHS):

    start_time = time.time()

    # ========================================================
    # TRAINING
    # ========================================================

    binary_model.train()

    running_train_loss = 0.0
    train_correct = 0
    train_total = 0

    for batch_images, batch_labels in train_loader:

        batch_images = batch_images.to(
            device,
            non_blocking=True
        )

        batch_labels = batch_labels.to(
            device,
            non_blocking=True
        )

        # Clear gradients
        binary_optimizer.zero_grad()

        # Forward pass
        outputs = binary_model(batch_images)

        # Loss
        loss = binary_criterion(
            outputs,
            batch_labels
        )

        # Backpropagation
        loss.backward()

        # Update weights
        binary_optimizer.step()

        # Statistics
        running_train_loss += (
            loss.item() * batch_images.size(0)
        )

        predictions = torch.argmax(
            outputs,
            dim=1
        )

        train_correct += (
            (predictions == batch_labels)
            .sum()
            .item()
        )

        train_total += batch_labels.size(0)

    train_loss = (
        running_train_loss /
        train_total
    )

    train_accuracy = (
        train_correct /
        train_total
    )

    # ========================================================
    # VALIDATION
    # ========================================================

    binary_model.eval()

    running_val_loss = 0.0
    val_correct = 0
    val_total = 0

    with torch.no_grad():

        for batch_images, batch_labels in val_loader:

            batch_images = batch_images.to(
                device,
                non_blocking=True
            )

            batch_labels = batch_labels.to(
                device,
                non_blocking=True
            )

            outputs = binary_model(
                batch_images
            )

            loss = binary_criterion(
                outputs,
                batch_labels
            )

            running_val_loss += (
                loss.item() *
                batch_images.size(0)
            )

            predictions = torch.argmax(
                outputs,
                dim=1
            )

            val_correct += (
                (predictions == batch_labels)
                .sum()
                .item()
            )

            val_total += batch_labels.size(0)

    val_loss = (
        running_val_loss /
        val_total
    )

    val_accuracy = (
        val_correct /
        val_total
    )

    # --------------------------------------------------------
    # Scheduler
    # --------------------------------------------------------

    binary_scheduler.step(
        val_loss
    )

    current_lr = (
        binary_optimizer
        .param_groups[0]["lr"]
    )

    # --------------------------------------------------------
    # Save history
    # --------------------------------------------------------

    history["train_loss"].append(
        train_loss
    )

    history["train_accuracy"].append(
        train_accuracy
    )

    history["val_loss"].append(
        val_loss
    )

    history["val_accuracy"].append(
        val_accuracy
    )

    # --------------------------------------------------------
    # Save best model
    # --------------------------------------------------------

    is_best = val_loss < best_val_loss

    if is_best:

        best_val_loss = val_loss

        torch.save(
            {
                "epoch": epoch + 1,
                "model_state_dict":
                    binary_model.state_dict(),
                "optimizer_state_dict":
                    binary_optimizer.state_dict(),
                "val_loss": val_loss,
                "val_accuracy": val_accuracy
            },
            BEST_MODEL_PATH
        )

    # --------------------------------------------------------
    # Epoch output
    # --------------------------------------------------------

    elapsed = time.time() - start_time

    marker = " ★ BEST" if is_best else ""

    print(
        f"Epoch {epoch+1:02d}/{NUM_EPOCHS} | "
        f"Train Loss: {train_loss:.4f} | "
        f"Train Acc: {train_accuracy:.4f} | "
        f"Val Loss: {val_loss:.4f} | "
        f"Val Acc: {val_accuracy:.4f} | "
        f"LR: {current_lr:.6f} | "
        f"Time: {elapsed:.1f}s"
        f"{marker}"
    )

# ------------------------------------------------------------
# Final information
# ------------------------------------------------------------

print("\n==============================================")
print("TRAINING COMPLETE")
print("==============================================")

print(
    "Best validation loss:",
    round(best_val_loss, 4)
)

print(
    "Best model saved to:"
)

print(BEST_MODEL_PATH)

print("\nSTEP 93 COMPLETE")

