import torch
import pandas as pd

from sklearn.metrics import (
    accuracy_score,
    precision_score,
    recall_score,
    f1_score,
    confusion_matrix,
    classification_report
)

print("==============================================")
print("BINARY MODEL TEST EVALUATION")
print("==============================================")

# ------------------------------------------------------------
# Load best checkpoint
# ------------------------------------------------------------

checkpoint = torch.load(
    BEST_MODEL_PATH,
    map_location=device
)

binary_model.load_state_dict(
    checkpoint["model_state_dict"]
)

binary_model = binary_model.to(device)
binary_model.eval()

print(
    "Best checkpoint epoch:",
    checkpoint["epoch"]
)

print(
    "Best validation loss:",
    round(
        checkpoint["val_loss"],
        4
    )
)

print(
    "Best validation accuracy:",
    round(
        checkpoint["val_accuracy"],
        4
    )
)

# ------------------------------------------------------------
# Test predictions
# ------------------------------------------------------------

all_predictions = []
all_labels = []
all_probabilities = []

with torch.no_grad():

    for batch_images, batch_labels in test_loader:

        batch_images = batch_images.to(
            device,
            non_blocking=True
        )

        outputs = binary_model(
            batch_images
        )

        probabilities = torch.softmax(
            outputs,
            dim=1
        )

        predictions = torch.argmax(
            outputs,
            dim=1
        )

        all_predictions.extend(
            predictions.cpu().numpy()
        )

        all_labels.extend(
            batch_labels.numpy()
        )

        all_probabilities.extend(
            probabilities.cpu().numpy()
        )

# ------------------------------------------------------------
# Convert to arrays
# ------------------------------------------------------------

all_labels = pd.Series(
    all_labels
).to_numpy()

all_predictions = pd.Series(
    all_predictions
).to_numpy()

# ------------------------------------------------------------
# Metrics
# ------------------------------------------------------------

accuracy = accuracy_score(
    all_labels,
    all_predictions
)

precision = precision_score(
    all_labels,
    all_predictions,
    average="weighted",
    zero_division=0
)

recall = recall_score(
    all_labels,
    all_predictions,
    average="weighted",
    zero_division=0
)

f1 = f1_score(
    all_labels,
    all_predictions,
    average="weighted",
    zero_division=0
)

macro_precision = precision_score(
    all_labels,
    all_predictions,
    average="macro",
    zero_division=0
)

macro_recall = recall_score(
    all_labels,
    all_predictions,
    average="macro",
    zero_division=0
)

macro_f1 = f1_score(
    all_labels,
    all_predictions,
    average="macro",
    zero_division=0
)

# ------------------------------------------------------------
# Display overall metrics
# ------------------------------------------------------------

print("\n==============================================")
print("OVERALL TEST METRICS")
print("==============================================")

print(
    f"Test Samples       : {len(all_labels)}"
)

print(
    f"Accuracy           : {accuracy:.4f}"
)

print(
    f"Weighted Precision : {precision:.4f}"
)

print(
    f"Weighted Recall    : {recall:.4f}"
)

print(
    f"Weighted F1        : {f1:.4f}"
)

print(
    f"Macro Precision    : {macro_precision:.4f}"
)

print(
    f"Macro Recall       : {macro_recall:.4f}"
)

print(
    f"Macro F1           : {macro_f1:.4f}"
)

# ------------------------------------------------------------
# Classification report
# ------------------------------------------------------------

print("\n==============================================")
print("CLASSIFICATION REPORT")
print("==============================================")

target_names = [
    "No Damage",
    "Damage"
]

print(
    classification_report(
        all_labels,
        all_predictions,
        target_names=target_names,
        digits=4,
        zero_division=0
    )
)

# ------------------------------------------------------------
# Confusion matrix
# ------------------------------------------------------------

cm = confusion_matrix(
    all_labels,
    all_predictions
)

print("\n==============================================")
print("CONFUSION MATRIX")
print("==============================================")

print(
    "Rows = Actual"
)

print(
    "Columns = Predicted"
)

print(
    "              No Damage   Damage"
)

print(
    f"No Damage     {cm[0,0]:9d}   {cm[0,1]:6d}"
)

print(
    f"Damage        {cm[1,0]:9d}   {cm[1,1]:6d}"
)

print("\n==============================================")
print("STEP 94 COMPLETE")
