import os
import torch
from PIL import Image
from torchvision import transforms

print("==============================================")
print("EXTERNAL IMAGE BINARY MODEL TEST")
print("==============================================")

# ------------------------------------------------------------
# Paths from our previous external-image testing
# ------------------------------------------------------------

clean_path = "/tmp/uploaded_clean_car_image.jpg"
damaged_path = "/tmp/uploaded_car_image.jpg"

# ------------------------------------------------------------
# Verify files
# ------------------------------------------------------------

print("Clean image exists  :", os.path.exists(clean_path))
print("Damaged image exists:", os.path.exists(damaged_path))

# ------------------------------------------------------------
# Load best binary model
# ------------------------------------------------------------

checkpoint = torch.load(
    BEST_MODEL_PATH,
    map_location=device
)

binary_model.load_state_dict(
    checkpoint["model_state_dict"]
)

binary_model.eval()

# ------------------------------------------------------------
# Evaluation transform
# ------------------------------------------------------------

binary_transform = transforms.Compose([
    transforms.Resize((224, 224)),
    transforms.ToTensor(),
    transforms.Normalize(
        mean=[0.485, 0.456, 0.406],
        std=[0.229, 0.224, 0.225]
    )
])

# ------------------------------------------------------------
# Prediction function
# ------------------------------------------------------------

def binary_predict(image_path):

    image = Image.open(
        image_path
    ).convert("RGB")

    tensor = binary_transform(
        image
    ).unsqueeze(0).to(device)

    with torch.no_grad():

        output = binary_model(
            tensor
        )

        probabilities = torch.softmax(
            output,
            dim=1
        )

        predicted_label = torch.argmax(
            probabilities,
            dim=1
        ).item()

    class_name = (
        "No Damage"
        if predicted_label == 0
        else "Damage"
    )

    confidence = (
        probabilities[0][predicted_label]
        .item()
        * 100
    )

    return {
        "class": class_name,
        "confidence": confidence,
        "no_damage_probability":
            probabilities[0][0].item() * 100,
        "damage_probability":
            probabilities[0][1].item() * 100,
        "image_size": image.size
    }

# ------------------------------------------------------------
# Test clean image
# ------------------------------------------------------------

print("\n==============================================")
print("CLEAN EXTERNAL IMAGE")
print("==============================================")

if os.path.exists(clean_path):

    clean_result = binary_predict(
        clean_path
    )

    print(
        "Image size:",
        clean_result["image_size"]
    )

    print(
        "Prediction:",
        clean_result["class"]
    )

    print(
        "Confidence:",
        f"{clean_result['confidence']:.2f}%"
    )

    print(
        "No Damage probability:",
        f"{clean_result['no_damage_probability']:.2f}%"
    )

    print(
        "Damage probability:",
        f"{clean_result['damage_probability']:.2f}%"
    )

else:

    print("Clean image not found.")

# ------------------------------------------------------------
# Test damaged image
# ------------------------------------------------------------

print("\n==============================================")
print("DAMAGED EXTERNAL IMAGE")
print("==============================================")

if os.path.exists(damaged_path):

    damaged_result = binary_predict(
        damaged_path
    )

    print(
        "Image size:",
        damaged_result["image_size"]
    )

    print(
        "Prediction:",
        damaged_result["class"]
    )

    print(
        "Confidence:",
        f"{damaged_result['confidence']:.2f}%"
    )

    print(
        "No Damage probability:",
        f"{damaged_result['no_damage_probability']:.2f}%"
    )

    print(
        "Damage probability:",
        f"{damaged_result['damage_probability']:.2f}%"
    )

else:

    print("Damaged image not found.")

print("\n==============================================")
print("STEP 96 COMPLETE")
print("==============================================")

