import pandas as pd
import numpy as np

print("==============================================")
print("BINARY MODEL ERROR & CONFIDENCE ANALYSIS")
print("==============================================")

# ------------------------------------------------------------
# Load saved test predictions
# ------------------------------------------------------------

pred_path = (
    "/content/drive/MyDrive/END SEM PROJECT-DL/"
    "outputs/binary_classification_model/"
    "binary_test_predictions.csv"
)

df = pd.read_csv(pred_path)

# ------------------------------------------------------------
# Basic statistics
# ------------------------------------------------------------

print("\nTotal test samples:", len(df))

print(
    "Correct predictions:",
    df["correct"].sum()
)

print(
    "Incorrect predictions:",
    (~df["correct"]).sum()
)

print(
    "Accuracy:",
    f"{df['correct'].mean() * 100:.2f}%"
)

# ------------------------------------------------------------
# Confidence of prediction
# ------------------------------------------------------------

df["prediction_confidence"] = np.where(
    df["predicted_label"] == 0,
    df["no_damage_probability"],
    df["damage_probability"]
)

# ------------------------------------------------------------
# Correct vs incorrect confidence
# ------------------------------------------------------------

correct_df = df[df["correct"] == True]
incorrect_df = df[df["correct"] == False]

print("\n==============================================")
print("CONFIDENCE ANALYSIS")
print("==============================================")

print(
    "Average confidence — Correct:",
    f"{correct_df['prediction_confidence'].mean() * 100:.2f}%"
)

print(
    "Average confidence — Incorrect:",
    f"{incorrect_df['prediction_confidence'].mean() * 100:.2f}%"
)

print(
    "Minimum confidence — Correct:",
    f"{correct_df['prediction_confidence'].min() * 100:.2f}%"
)

print(
    "Maximum confidence — Incorrect:",
    f"{incorrect_df['prediction_confidence'].max() * 100:.2f}%"
)

# ------------------------------------------------------------
# Confidence ranges
# ------------------------------------------------------------

print("\n==============================================")
print("CONFIDENCE RANGES")
print("==============================================")

bins = [0, 0.60, 0.80, 0.90, 0.95, 1.00]
labels = [
    "<60%",
    "60–80%",
    "80–90%",
    "90–95%",
    "95–100%"
]

df["confidence_range"] = pd.cut(
    df["prediction_confidence"],
    bins=bins,
    labels=labels,
    include_lowest=True
)

confidence_summary = (
    df.groupby(
        "confidence_range",
        observed=False
    )
    .agg(
        total=("correct", "count"),
        correct=("correct", "sum")
    )
)

confidence_summary["incorrect"] = (
    confidence_summary["total"]
    - confidence_summary["correct"]
)

confidence_summary["accuracy"] = (
    confidence_summary["correct"]
    / confidence_summary["total"]
    * 100
)

print(confidence_summary)

# ------------------------------------------------------------
# Class-wise performance
# ------------------------------------------------------------

print("\n==============================================")
print("CLASS-WISE PERFORMANCE")
print("==============================================")

for cls in ["No Damage", "Damage"]:

    class_df = df[
        df["actual_class"] == cls
    ]

    accuracy = class_df["correct"].mean() * 100

    print(
        f"{cls}: "
        f"{class_df['correct'].sum()}/"
        f"{len(class_df)} correct "
        f"({accuracy:.2f}%)"
    )

# ------------------------------------------------------------
# Misclassification details
# ------------------------------------------------------------

print("\n==============================================")
print("MISCLASSIFICATION CONFIDENCE")
print("==============================================")

misclassified = df[
    df["correct"] == False
][[
    "image",
    "actual_class",
    "predicted_class",
    "prediction_confidence",
    "no_damage_probability",
    "damage_probability"
]].copy()

misclassified["prediction_confidence"] *= 100
misclassified["no_damage_probability"] *= 100
misclassified["damage_probability"] *= 100

print(
    misclassified.to_string(index=False)
)

print("\n==============================================")
print("STEP 97 COMPLETE")
print("==============================================")

