# ============================================================
# STEP 99 — FIX CLASS MAPPING AND VERIFY MODELS
# ============================================================

import os
import json
import torch

print("==============================================")
print("FIXING CLASS MAPPING")
print("==============================================")

# ------------------------------------------------------------
# Load class mapping
# ------------------------------------------------------------

CLASS_MAPPING_PATH = (
    "/content/drive/MyDrive/END SEM PROJECT-DL/"
    "outputs/classification_dataset/"
    "class_mapping.json"
)

with open(CLASS_MAPPING_PATH, "r") as f:
    class_to_idx = json.load(f)

print("\nRaw class mapping:")
print(class_to_idx)

# ------------------------------------------------------------
# Handle the actual JSON structure
# ------------------------------------------------------------

if "class_to_idx" in class_to_idx:

    class_to_idx = class_to_idx["class_to_idx"]

elif "mapping" in class_to_idx:

    class_to_idx = class_to_idx["mapping"]

# ------------------------------------------------------------
# Convert values safely
# ------------------------------------------------------------

idx_to_class = {}

for class_name, value in class_to_idx.items():

    if isinstance(value, dict):

        # Handle nested mapping structures
        if "index" in value:
            index = value["index"]

        elif "idx" in value:
            index = value["idx"]

        else:
            # Try the first numeric value
            numeric_values = [
                x for x in value.values()
                if isinstance(x, (int, float))
            ]

            if len(numeric_values) == 0:
                raise ValueError(
                    f"Could not determine class index for "
                    f"{class_name}: {value}"
                )

            index = numeric_values[0]

    else:

        index = value

    idx_to_class[int(index)] = class_name

# ------------------------------------------------------------
# Display final mapping
# ------------------------------------------------------------

print("\nFinal class mapping:")

for idx in sorted(idx_to_class):

    print(
        f"{idx}: {idx_to_class[idx]}"
    )

# ------------------------------------------------------------
# Verify expected 8 classes
# ------------------------------------------------------------

print(
    "\nNumber of classes:",
    len(idx_to_class)
)

expected_classes = [
    "bumper_dent",
    "bumper_scratch",
    "door_dent",
    "door_scratch",
    "glass_shatter",
    "head_lamp",
    "tail_lamp",
    "unknown"
]

missing_classes = [
    cls for cls in expected_classes
    if cls not in idx_to_class.values()
]

if len(missing_classes) == 0:

    print(
        "Class mapping verification: PASSED"
    )

else:

    print(
        "Missing classes:",
        missing_classes
    )

print("\n==============================================")
print("STEP 99 COMPLETE")
print("==============================================")

