import numpy as np
from PIL import Image

print("==============================================")
print("CREATING FINAL ASSESSMENT FUNCTION")
print("==============================================")

def predict_vehicle_damage(image_path):

    # ========================================================
    # 1. LOAD IMAGE
    # ========================================================

    image = Image.open(
        image_path
    ).convert("RGB")

    # ========================================================
    # 2. BINARY DAMAGE DETECTION
    # ========================================================

    binary_tensor = (
        classification_transform(image)
        .unsqueeze(0)
        .to(device)
    )

    with torch.no_grad():

        binary_output = binary_model(
            binary_tensor
        )

        binary_probabilities = torch.softmax(
            binary_output,
            dim=1
        )[0]

    no_damage_probability = (
        binary_probabilities[0].item()
    )

    damage_probability = (
        binary_probabilities[1].item()
    )

    binary_prediction = torch.argmax(
        binary_probabilities
    ).item()

    # ========================================================
    # 3. NO-DAMAGE GATE
    # ========================================================

    if binary_prediction == 0:

        return {
            "image": image_path,
            "damage_status": "No Damage",
            "damage_type": "No Damage",
            "damage_type_confidence": 0.0,
            "damage_percentage": 0.0,
            "severity": "No Significant Damage",
            "assessment_score": 0,
            "insurance_status": "Not Eligible",
            "binary_no_damage_probability":
                no_damage_probability,
            "binary_damage_probability":
                damage_probability
        }

    # ========================================================
    # 4. DAMAGE TYPE CLASSIFICATION
    # ========================================================

    class_tensor = (
        classification_transform(image)
        .unsqueeze(0)
        .to(device)
    )

    with torch.no_grad():

        class_output = classification_model(
            class_tensor
        )

        class_probabilities = torch.softmax(
            class_output,
            dim=1
        )[0]

    class_prediction = torch.argmax(
        class_probabilities
    ).item()

    damage_type = idx_to_class[
        class_prediction
    ]

    damage_type_confidence = (
        class_probabilities[
            class_prediction
        ].item()
    )

    # ========================================================
    # 5. DAMAGE SEGMENTATION
    # ========================================================

    segmentation_tensor = (
        segmentation_transform(image)
        .unsqueeze(0)
        .to(device)
    )

    with torch.no_grad():

        segmentation_output = segmentation_model(
            segmentation_tensor
        )

        segmentation_probability = torch.sigmoid(
            segmentation_output
        )[0, 0]

    # Calibrated threshold from Phase 3
    SEGMENTATION_THRESHOLD = 0.60

    damage_mask = (
        segmentation_probability
        >= SEGMENTATION_THRESHOLD
    )

    damage_pixels = (
        damage_mask.sum().item()
    )

    total_pixels = (
        damage_mask.numel()
    )

    damage_percentage = (
        damage_pixels /
        total_pixels *
        100
    )

    # ========================================================
    # 6. SEVERITY AND PROJECT SCORE
    # ========================================================

    if damage_percentage < 2.5:

        severity = "No Significant Damage"
        assessment_score = 0
        insurance_status = "Not Eligible"

    elif damage_percentage < 5:

        severity = "Low"
        assessment_score = 25
        insurance_status = "Eligible"

    elif damage_percentage < 15:

        severity = "Moderate"
        assessment_score = 50
        insurance_status = "Eligible"

    elif damage_percentage < 30:

        severity = "High"
        assessment_score = 75
        insurance_status = "Eligible"

    else:

        severity = "Very High"
        assessment_score = 100
        insurance_status = "Eligible"

    # ========================================================
    # 7. FINAL RESULT
    # ========================================================

    return {
        "image": image_path,
        "damage_status": "Damage",
        "damage_type": damage_type,
        "damage_type_confidence":
            damage_type_confidence,
        "damage_percentage":
            damage_percentage,
        "severity": severity,
        "assessment_score":
            assessment_score,
        "insurance_status":
            insurance_status,
        "binary_no_damage_probability":
            no_damage_probability,
        "binary_damage_probability":
            damage_probability
    }


print("\n✓ Final prediction function created")

print("\nPipeline:")
print("1. Binary Damage Detection")
print("2. Damage Type Classification")
print("3. Damage Segmentation")
print("4. Damage Severity")
print("5. Assessment Score")
