print("Raw Damage probability:", binary_damage_prob)

print("No Damage percentage:", f"{binary_no_damage_prob * 100:.2f}%")
print("Damage percentage:", f"{binary_damage_prob * 100:.2f}%")

# ------------------------------------------------------------
# DAMAGE TYPE MODEL
# ------------------------------------------------------------

classification_model.eval()

with torch.no_grad():
    class_output = classification_model(input_tensor)
    class_probs = F.softmax(class_output, dim=1)[0]

class_confidence, class_index = torch.max(class_probs, dim=0)

class_confidence_raw = class_confidence.item()
class_name = idx_to_class[int(class_index.item())]

