# ============================================================
# STEP 110 — FIX CONFIDENCE DISPLAY FORMAT
# ============================================================

def predict_vehicle_damage(image_path):

    # --------------------------------------------------------
    # 1. LOAD IMAGE
    # --------------------------------------------------------
    image = Image.open(image_path).convert("RGB")

    # --------------------------------------------------------
    # 2. BINARY DAMAGE DETECTION
    # --------------------------------------------------------
    binary_input = binary_transform(image).unsqueeze(0).to(device)

    binary_model.eval()

    with torch.no_grad():
        binary_output = binary_model(binary_input)
        binary_probs = F.softmax(binary_output, dim=1)[0]

    no_damage_prob = binary_probs[0].item()
    damage_prob = binary_probs[1].item()

    binary_index = torch.argmax(binary_probs).item()

    # --------------------------------------------------------
    # NO DAMAGE
    # --------------------------------------------------------
    if binary_index == 0:

        return {
            "damage_status": "No Damage",
            "damage_status_confidence": no_damage_prob * 100,
            "damage_type": "No Damage",
            "damage_type_confidence": 0.0,
            "damage_percentage": 0.0,
            "severity": "No Significant Damage",
            "severity_score": 0,
            "assessment_score": 0,
            "category": "No Significant Damage",
            "insurance_status": "Not Eligible"
        }

    # --------------------------------------------------------
    # 3. DAMAGE TYPE CLASSIFICATION
    # --------------------------------------------------------
    classification_model.eval()

    with torch.no_grad():
        class_output = classification_model(binary_input)
        class_probs = F.softmax(class_output, dim=1)[0]

    class_confidence, class_index = torch.max(class_probs, dim=0)

    damage_type = idx_to_class[int(class_index.item())]

    # IMPORTANT:
    # Convert probability (0-1) to percentage (0-100)
    damage_type_confidence = class_confidence.item() * 100

    # --------------------------------------------------------
    # 4. DAMAGE SEGMENTATION
    # --------------------------------------------------------
    segmentation_model.eval()

    seg_input = segmentation_transform(image).unsqueeze(0).to(device)

    with torch.no_grad():
        segmentation_output = segmentation_model(seg_input)
        segmentation_prob = torch.sigmoid(segmentation_output)

    # Threshold = 0.60
    segmentation_mask = (segmentation_prob >= 0.60).float()

    damage_pixels = segmentation_mask.sum().item()

    total_pixels = (
        segmentation_mask.shape[-1] *
        segmentation_mask.shape[-2]
    )

    damage_percentage = (
        damage_pixels / total_pixels
    ) * 100

    # --------------------------------------------------------
    # 5. SEVERITY + SCORE
    # --------------------------------------------------------
    if damage_percentage < 2.5:

        severity = "No Significant Damage"
        severity_score = 0
        insurance_status = "Not Eligible"

    elif damage_percentage < 5:

        severity = "Low"
        severity_score = 25
        insurance_status = "Eligible"

    elif damage_percentage < 15:

        severity = "Moderate"
        severity_score = 50
        insurance_status = "Eligible"

    elif damage_percentage < 30:

        severity = "High"
        severity_score = 75
        insurance_status = "Eligible"

    else:

        severity = "Very High"
        severity_score = 100
        insurance_status = "Eligible"

    # --------------------------------------------------------
    # 6. FINAL RESULT
    # --------------------------------------------------------
    return {

        "damage_status": "Damage",

        "damage_status_confidence":
            damage_prob * 100,

        "damage_type":
            damage_type,

        "damage_type_confidence":
            damage_type_confidence,

        "damage_percentage":
            damage_percentage,

        "severity":
            severity,

        "severity_score":
            severity_score,

        "assessment_score":
            severity_score,

        "category":
            severity,

        "insurance_status":
            insurance_status
    }


print("=" * 60)
print("STEP 110 — CONFIDENCE FORMAT FIXED")
print("=" * 60)

