# STEP 113 — SCORE-BASED FINAL PREDICTION FUNCTION
# ============================================================

def predict_vehicle_damage_detailed(image_path):

    image = Image.open(image_path).convert("RGB")

    # ========================================================
    # 1. BINARY DAMAGE DETECTION
    # ========================================================

    binary_input = binary_transform(image).unsqueeze(0).to(device)

    binary_model.eval()

    with torch.no_grad():
        binary_output = binary_model(binary_input)
        binary_probs = F.softmax(binary_output, dim=1)[0]

    no_damage_prob = binary_probs[0].item()
    damage_prob = binary_probs[1].item()

    binary_index = torch.argmax(binary_probs).item()

    # ========================================================
    # NO DAMAGE
    # ========================================================

    if binary_index == 0:

        return {
            "damage_status": "No Damage",

            "no_damage_probability":
                no_damage_prob * 100,

            "damage_probability":
                damage_prob * 100,

            "damage_type":
                "No Damage",

            "damage_type_confidence":
                0.0,

            "class_probabilities": {},

            "damage_percentage":
                0.0,

            "severity":
                "No Significant Damage",

            "assessment_score":
                0,

            "insurance_status":
                "Not Eligible"
        }

    # ========================================================
    # 2. DAMAGE TYPE CLASSIFICATION
    # ========================================================

    classification_model.eval()

    with torch.no_grad():
        class_output = classification_model(binary_input)
        class_probs = F.softmax(class_output, dim=1)[0]

    class_confidence, class_index = torch.max(
        class_probs,
        dim=0
    )

    damage_type = idx_to_class[
        int(class_index.item())
    ]

    # Convert every class probability to percentage
    class_probabilities = {}

    for idx, probability in enumerate(class_probs):

        class_name = idx_to_class[idx]

        class_probabilities[class_name] = (
            probability.item() * 100
        )

    # ========================================================
    # 3. DAMAGE SEGMENTATION
    # ========================================================

    segmentation_model.eval()

    seg_input = segmentation_transform(
        image
    ).unsqueeze(0).to(device)

    with torch.no_grad():

        segmentation_output = segmentation_model(
            seg_input
        )

        segmentation_prob = torch.sigmoid(
            segmentation_output
        )

    # Threshold selected during project evaluation
    segmentation_mask = (
        segmentation_prob >= 0.60
    ).float()

    damage_pixels = segmentation_mask.sum().item()

    total_pixels = (
        segmentation_mask.shape[-1] *
        segmentation_mask.shape[-2]
    )

    damage_percentage = (
        damage_pixels /
        total_pixels
    ) * 100

    # ========================================================
    # 4. SEVERITY + SCORE
    # ========================================================

    if damage_percentage < 2.5:

        severity = "No Significant Damage"
        assessment_score = 0
        insurance_status = "Not Eligible"

    elif damage_percentage < 5:

        severity = "Low"
        assessment_score = 25
        insurance_status = "Eligible"

    elif damage_percentage < 15:

        severity = "Moderate"
        assessment_score = 50
        insurance_status = "Eligible"

    elif damage_percentage < 30:

        severity = "High"
        assessment_score = 75
        insurance_status = "Eligible"

    else:

        severity = "Very High"
        assessment_score = 100
        insurance_status = "Eligible"

    # ========================================================
    # 5. RETURN COMPLETE SCORE INFORMATION
    # ========================================================

    return {

        "damage_status":
            "Damage",

        "no_damage_probability":
            no_damage_prob * 100,

        "damage_probability":
            damage_prob * 100,

        "damage_type":
            damage_type,

        "damage_type_confidence":
            class_confidence.item() * 100,

        "class_probabilities":
            class_probabilities,

        "damage_percentage":
            damage_percentage,

        "severity":
            severity,

        "assessment_score":
            assessment_score,

        "insurance_status":
            insurance_status
    }


print("=" * 70)
print("STEP 113 — SCORE-BASED PREDICTION FUNCTION")
print("=" * 70)

print("\nDetailed prediction function created.")
print("Returns binary probabilities + all damage-type probabilities")
print("+ damage area + severity + assessment score.")

