import torch
import torch.nn.functional as F
from PIL import Image

print("=" * 70)
print("STEP 73 — RESTORING PREVIOUS WORKING PIPELINE")
print("=" * 70)


def predict_vehicle_damage(image_path):

    # -----------------------------------------------------
    # LOAD IMAGE
    # -----------------------------------------------------

    image = Image.open(image_path).convert("RGB")


    # -----------------------------------------------------
    # DAMAGE TYPE CLASSIFICATION
    # -----------------------------------------------------

    classification_input = classification_transform(image)

    classification_input = (
        classification_input
        .unsqueeze(0)
        .to(device)
    )

    with torch.no_grad():

        classification_output = classification_model(
            classification_input
        )

        classification_probabilities = F.softmax(
            classification_output,
            dim=1
        )[0]


    predicted_class_index = torch.argmax(
        classification_probabilities
    ).item()


    damage_type = idx_to_class[
        predicted_class_index
    ]


    classification_confidence = (
        classification_probabilities[
            predicted_class_index
        ].item() * 100
    )


    # -----------------------------------------------------
    # SEGMENTATION
    # -----------------------------------------------------

    segmentation_input = segmentation_transform(image)

    segmentation_input = (
        segmentation_input
        .unsqueeze(0)
        .to(device)
    )


    with torch.no_grad():

        segmentation_output = segmentation_model(
            segmentation_input
        )

        segmentation_probability = torch.sigmoid(
            segmentation_output
        )[0, 0]


    # Previous segmentation threshold
    segmentation_mask = (
        segmentation_probability >= 0.60
    )


    damage_pixels = (
        segmentation_mask.sum().item()
    )

    total_pixels = (
        segmentation_mask.numel()
    )


    damage_percentage = (
        damage_pixels / total_pixels
    ) * 100


    # -----------------------------------------------------
    # PREVIOUS SEVERITY LOGIC
    # -----------------------------------------------------

    if damage_percentage < 5:

        severity = "Low"

    elif damage_percentage < 15:

        severity = "Moderate"

    elif damage_percentage < 30:

        severity = "High"

    else:

        severity = "Very High"


    # -----------------------------------------------------
    # PREVIOUS ASSESSMENT SCORE
    # -----------------------------------------------------

    assessment_score = (
        0.60 * damage_percentage
        +
        0.40 * classification_confidence
    )


    # -----------------------------------------------------
    # PREVIOUS ASSESSMENT CATEGORY
    # -----------------------------------------------------

    if assessment_score < 25:

        assessment_category = "Low Assessment"

    elif assessment_score < 50:

        assessment_category = "Moderate Assessment"

    elif assessment_score < 75:

        assessment_category = "High Assessment"

    else:

        assessment_category = "Very High Assessment"


    # -----------------------------------------------------
    # PREVIOUS INSURANCE RULE
    # -----------------------------------------------------

    if assessment_score >= 25:

        insurance_status = "Insurance Eligible"

    else:

        insurance_status = "Not Insurance Eligible"


    # -----------------------------------------------------
    # RETURN EXACT KEYS USED BY OLD GRADIO
    # -----------------------------------------------------

    return {

        "damage_type": damage_type,

        "classification_confidence":
            classification_confidence,

        "damage_percentage":
            damage_percentage,

        "severity":
            severity,

        "assessment_score":
            assessment_score,

        "assessment_category":
            assessment_category,

        "insurance_status":
            insurance_status
    }


print("\nPrevious prediction pipeline restored successfully.")

