# RECOVER THE COMMON INTERNAL TEST IMAGES
# Match using the image number, not the filename

import os
import re
import shutil
import pandas as pd
from PIL import Image
from IPython.display import display

PROJECT = "/content/drive/MyDrive/END SEM PROJECT-DL"

CLASS_TEST = f"{PROJECT}/outputs/classification_dataset/splits/test.csv"
SEG_TEST = f"{PROJECT}/outputs/segmentation_dataset/splits/test.csv"

OUTPUT_DIR = f"{PROJECT}/outputs/internal_test_images/classification_segmentation_overlap"
os.makedirs(OUTPUT_DIR, exist_ok=True)

# --------------------------------------------------
# 1. Load test splits
# --------------------------------------------------
class_df = pd.read_csv(CLASS_TEST)
seg_df = pd.read_csv(SEG_TEST)

# --------------------------------------------------
# 2. Extract numeric image ID
# --------------------------------------------------
def extract_id(value):
    name = os.path.basename(str(value))
    match = re.search(r'(\d+)', name)
    return int(match.group(1)) if match else None

class_df["image_id"] = class_df["image"].apply(extract_id)
seg_df["image_id"] = seg_df["image_name"].apply(extract_id)

# --------------------------------------------------
# 3. Find common IDs
# --------------------------------------------------
common_ids = sorted(
    set(class_df["image_id"].dropna()) &
    set(seg_df["image_id"].dropna())
)

print("Classification test images :", len(class_df))
print("Segmentation test images   :", len(seg_df))
print("Common image IDs           :", len(common_ids))

print("\nCommon IDs:")
print(common_ids)

# --------------------------------------------------
# 4. Create output dataframe
# --------------------------------------------------
rows = []

for i, image_id in enumerate(common_ids, start=1):

    c = class_df[class_df["image_id"] == image_id].iloc[0]
    s = seg_df[seg_df["image_id"] == image_id].iloc[0]

    rows.append({
        "test_number": i,
        "image_id": image_id,
        "classification_image": c["image"],
        "classification_class": c["classes"],
        "classification_label": c["label"],
        "segmentation_image": s["image"],
        "segmentation_mask": s["mask"],
        "segmentation_image_name": s["image_name"]
    })

overlap_df = pd.DataFrame(rows)

# --------------------------------------------------
# 5. Copy actual images
# --------------------------------------------------
saved_rows = []

for _, row in overlap_df.iterrows():

    source = row["segmentation_image"]

    if not os.path.exists(source):
        print("MISSING:", source)
        continue

    original_ext = os.path.splitext(source)[1]

    new_name = f"internal_test_{int(row['test_number']):02d}_ID_{int(row['image_id'])}{original_ext}"

    destination = os.path.join(
        OUTPUT_DIR,
        new_name
    )

    shutil.copy2(source, destination)

    saved_rows.append({
        **row.to_dict(),
        "saved_image": destination
    })

saved_df = pd.DataFrame(saved_rows)

# --------------------------------------------------
# 6. Save CSV
# --------------------------------------------------
CSV_OUTPUT = f"{PROJECT}/outputs/internal_test_images/internal_test_21.csv"

saved_df.to_csv(CSV_OUTPUT, index=False)

# --------------------------------------------------
# 7. Final result
# --------------------------------------------------
print("\n============================================")
print("INTERNAL TEST SET CREATED")
print("============================================")

print("Common images found :", len(common_ids))
print("Images actually saved:", len(saved_df))

print("\nFolder:")
print(OUTPUT_DIR)

print("\nCSV:")
print(CSV_OUTPUT)

print("\n============================================")
print("IMAGE LIST")
print("============================================")

display(
    saved_df[
        [
            "test_number",
            "image_id",
            "classification_class",
            "classification_label",
            "saved_image"
        ]
    ]
)

# --------------------------------------------------
# 8. Display all saved images
# --------------------------------------------------
print("\n============================================")
print("DISPLAYING INTERNAL TEST IMAGES")
print("============================================")

for _, row in saved_df.iterrows():

    img = Image.open(row["saved_image"]).convert("RGB")

    print(
        f"Test {int(row['test_number']):02d} | "
        f"ID: {int(row['image_id'])} | "
        f"Class: {row['classification_class']} | "
        f"Label: {int(row['classification_label'])}"
    )

    display(img.resize((350, 250)))

