# STEP 73G — RESTORING TRAINED U-NET + RESNET18 SEGMENTATION MODEL

import torch
import torch.nn as nn
import torch.nn.functional as F
from torchvision import models

print("=" * 70)
print("STEP 73G — RESTORING TRAINED SEGMENTATION MODEL")
print("=" * 70)


# ------------------------------------------------------------
# Basic convolution block
# ------------------------------------------------------------
class ConvBlock(nn.Module):
    def __init__(self, in_channels, out_channels):
        super().__init__()

        self.block = nn.Sequential(
            nn.Conv2d(
                in_channels,
                out_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.BatchNorm2d(out_channels),
            nn.ReLU(inplace=True),

            nn.Conv2d(
                out_channels,
                out_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.BatchNorm2d(out_channels),
            nn.ReLU(inplace=True)
        )

    def forward(self, x):
        return self.block(x)


# ------------------------------------------------------------
# Decoder block
# ------------------------------------------------------------
class DecoderBlock(nn.Module):
    def __init__(self, in_channels, skip_channels, out_channels):
        super().__init__()

        self.up = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size=2,
            stride=2
        )

        self.conv = ConvBlock(
            out_channels + skip_channels,
            out_channels
        )

    def forward(self, x, skip):
        x = self.up(x)

        # Handle possible spatial-size differences
        if x.shape[-2:] != skip.shape[-2:]:
            x = F.interpolate(
                x,
                size=skip.shape[-2:],
                mode="bilinear",
                align_corners=False
            )

        x = torch.cat([x, skip], dim=1)
        return self.conv(x)


# ------------------------------------------------------------
# U-Net with ResNet18 encoder
# ------------------------------------------------------------
class UNetResNet18(nn.Module):
    def __init__(self):
        super().__init__()

        resnet = models.resnet18(weights=None)

        # Encoder
        self.enc1 = nn.Sequential(
            resnet.conv1,
            resnet.bn1,
            resnet.relu
        )

        self.pool1 = resnet.maxpool

        self.enc2 = resnet.layer1
        self.enc3 = resnet.layer2
        self.enc4 = resnet.layer3
        self.enc5 = resnet.layer4

        # Decoder
        self.dec4 = DecoderBlock(512, 256, 256)
        self.dec3 = DecoderBlock(256, 128, 128)
        self.dec2 = DecoderBlock(128, 64, 64)
        self.dec1 = DecoderBlock(64, 64, 64)

        # Final upsampling
        self.final_up = nn.ConvTranspose2d(
            64,
            32,
            kernel_size=2,
            stride=2
        )

        self.final_conv = nn.Conv2d(
            32,
            1,
            kernel_size=1
        )

    def forward(self, x):

        # Encoder
        e1 = self.enc1(x)
        p1 = self.pool1(e1)

        e2 = self.enc2(p1)
        e3 = self.enc3(e2)
        e4 = self.enc4(e3)
        e5 = self.enc5(e4)

        # Decoder
        d4 = self.dec4(e5, e4)
        d3 = self.dec3(d4, e3)
        d2 = self.dec2(d3, e2)
        d1 = self.dec1(d2, e1)

        # Final output
        out = self.final_up(d1)
        out = self.final_conv(out)

        # Ensure output is exactly 256 × 256
        out = F.interpolate(
            out,
            size=(256, 256),
            mode="bilinear",
            align_corners=False
        )

        return out


# ------------------------------------------------------------
# Create model
# ------------------------------------------------------------
segmentation_model = UNetResNet18().to(device)

print("\nModel created.")
print("Device:", device)

print("\nModel parameter count:")
print(sum(p.numel() for p in segmentation_model.parameters()))


# ------------------------------------------------------------
# Load trained checkpoint
# ------------------------------------------------------------
segmentation_model.load_state_dict(
    checkpoint["model_state_dict"]
)

segmentation_model.eval()

print("\nTrained weights loaded successfully.")
print("Architecture: U-Net + ResNet18 encoder")
print("Output channels: 1")
print("Input size: 256 × 256")
print("\nSTEP 73G completed successfully.")

# STEP 73H — EXACT U-NET ARCHITECTURE FROM CHECKPOINT KEYS

import torch
import torch.nn as nn
import torch.nn.functional as F
from torchvision import models

print("=" * 70)
print("STEP 73H — RESTORING EXACT TRAINED SEGMENTATION ARCHITECTURE")
print("=" * 70)


# ------------------------------------------------------------
# Convolution block
# Matches checkpoint names:
# dec4.block.0
# dec4.block.1
# dec4.block.3
# dec4.block.4
# ------------------------------------------------------------
class DecoderConvBlock(nn.Module):
    def __init__(self, in_channels, out_channels):
        super().__init__()

        self.block = nn.Sequential(
            nn.Conv2d(
                in_channels,
                out_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.BatchNorm2d(out_channels),
            nn.ReLU(inplace=True),

            nn.Conv2d(
                out_channels,
                out_channels,
                kernel_size=3,
                padding=1,
                bias=False
            ),
            nn.BatchNorm2d(out_channels),
            nn.ReLU(inplace=True)
        )

    def forward(self, x):
        return self.block(x)


# ------------------------------------------------------------
# Exact U-Net + ResNet18 structure
# ------------------------------------------------------------
class UNetResNet18Exact(nn.Module):

    def __init__(self):
        super().__init__()

        resnet = models.resnet18(weights=None)

        # Encoder
        self.enc1 = nn.Sequential(
            resnet.conv1,
            resnet.bn1,
            resnet.relu
        )

        self.pool1 = resnet.maxpool

        self.enc2 = resnet.layer1
        self.enc3 = resnet.layer2
        self.enc4 = resnet.layer3
        self.enc5 = resnet.layer4

        # Decoder upsampling layers
        self.up4 = nn.ConvTranspose2d(
            512, 256,
            kernel_size=2,
            stride=2
        )

        self.up3 = nn.ConvTranspose2d(
            256, 128,
            kernel_size=2,
            stride=2
        )

        self.up2 = nn.ConvTranspose2d(
            128, 64,
            kernel_size=2,
            stride=2
        )

        self.up1 = nn.ConvTranspose2d(
            64, 64,
            kernel_size=2,
            stride=2
        )

        # Decoder convolution blocks
        self.dec4 = DecoderConvBlock(
            512, 256
        )

        self.dec3 = DecoderConvBlock(
            256, 128
        )

        self.dec2 = DecoderConvBlock(
            128, 64
        )

        self.dec1 = DecoderConvBlock(
            128, 64
        )

        # Final layers
        self.final_up = nn.ConvTranspose2d(
            64, 32,
            kernel_size=2,
            stride=2
        )

        self.final_conv = nn.Conv2d(
            32, 1,
            kernel_size=1
        )

    def forward(self, x):

        # Encoder
        e1 = self.enc1(x)
        p1 = self.pool1(e1)

        e2 = self.enc2(p1)
        e3 = self.enc3(e2)
        e4 = self.enc4(e3)
        e5 = self.enc5(e4)

        # Decoder 4
        x = self.up4(e5)

        if x.shape[-2:] != e4.shape[-2:]:
            x = F.interpolate(
                x,
                size=e4.shape[-2:],
                mode="bilinear",
                align_corners=False
            )

        x = torch.cat([x, e4], dim=1)
        x = self.dec4(x)

        # Decoder 3
        x = self.up3(x)

        if x.shape[-2:] != e3.shape[-2:]:
            x = F.interpolate(
                x,
                size=e3.shape[-2:],
                mode="bilinear",
                align_corners=False
            )

        x = torch.cat([x, e3], dim=1)
        x = self.dec3(x)

        # Decoder 2
        x = self.up2(x)

        if x.shape[-2:] != e2.shape[-2:]:
            x = F.interpolate(
                x,
                size=e2.shape[-2:],
                mode="bilinear",
                align_corners=False
            )

        x = torch.cat([x, e2], dim=1)
        x = self.dec2(x)

        # Decoder 1
        x = self.up1(x)

        if x.shape[-2:] != e1.shape[-2:]:
            x = F.interpolate(
                x,
                size=e1.shape[-2:],
                mode="bilinear",
                align_corners=False
            )

        x = torch.cat([x, e1], dim=1)
        x = self.dec1(x)

        # Final prediction
        x = self.final_up(x)
        x = self.final_conv(x)

        x = F.interpolate(
            x,
            size=(256, 256),
            mode="bilinear",
            align_corners=False
        )

        return x


# ------------------------------------------------------------
# Create model
# ------------------------------------------------------------
segmentation_model = UNetResNet18Exact().to(device)

print("\nModel created.")
print("Device:", device)

print("\nModel parameter count:")
print(sum(p.numel() for p in segmentation_model.parameters()))


# ------------------------------------------------------------
# Load trained weights
# ------------------------------------------------------------
segmentation_model.load_state_dict(
    checkpoint["model_state_dict"]
)

segmentation_model.eval()

print("\nTrained weights loaded successfully.")
print("Architecture: U-Net + ResNet18 encoder")
print("Input size: 256 × 256")
print("Output channels: 1")

print("\nSTEP 73H completed successfully.")

