# STEP 74 — COMPLETE PREDICTION FUNCTION
# Self-contained transforms — no classification_transform error
# ============================================================

import os
import torch
import torch.nn.functional as F
from PIL import Image
from torchvision import transforms

# ------------------------------------------------------------
# Device
# ------------------------------------------------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

print("Device:", device)

# ------------------------------------------------------------
# Check required models
# ------------------------------------------------------------
required_models = [
    "classification_model",
    "segmentation_model"
]

for model_name in required_models:
    if model_name not in globals():
        raise NameError(
            f"{model_name} is not loaded in this Colab runtime. "
            f"Please run the model-loading cell before STEP 74."
        )

# ------------------------------------------------------------
# Class mapping
# ------------------------------------------------------------
idx_to_class = {
    0: "bumper_dent",
    1: "bumper_scratch",
    2: "door_dent",
    3: "door_scratch",
    4: "glass_shatter",
    5: "head_lamp",
    6: "tail_lamp",
    7: "unknown"
}

# ------------------------------------------------------------
# Prediction function
# ------------------------------------------------------------
def predict_vehicle_damage(image_path):

    # ========================================================
    # IMAGE
    # ========================================================
    image = Image.open(image_path).convert("RGB")

    # ========================================================
    # CLASSIFICATION TRANSFORM
    # Defined INSIDE function so it can never be missing
    # ========================================================
    classification_transform_local = transforms.Compose([
        transforms.Resize((224, 224)),
        transforms.ToTensor(),
        transforms.Normalize(
            mean=[0.485, 0.456, 0.406],
            std=[0.229, 0.224, 0.225]
        )
    ])

    # ========================================================
    # SEGMENTATION TRANSFORM
    # ========================================================
    segmentation_transform_local = transforms.Compose([
        transforms.Resize((256, 256)),
        transforms.ToTensor(),
        transforms.Normalize(
            mean=[0.485, 0.456, 0.406],
            std=[0.229, 0.224, 0.225]
        )
    ])

    # ========================================================
    # 1. DAMAGE CLASSIFICATION
    # ========================================================
    classification_input = classification_transform_local(image)
    classification_input = classification_input.unsqueeze(0).to(device)

    classification_model.eval()

    with torch.no_grad():

        classification_output = classification_model(
            classification_input
        )

        classification_probabilities = F.softmax(
            classification_output,
            dim=1
        )[0]

    predicted_class_index = torch.argmax(
        classification_probabilities
    ).item()

    damage_type = idx_to_class[predicted_class_index]

    classification_confidence = (
        classification_probabilities[
            predicted_class_index
        ].item() * 100
    )

    # ========================================================
    # 2. DAMAGE SEGMENTATION
    # ========================================================
    segmentation_input = segmentation_transform_local(image)
    segmentation_input = segmentation_input.unsqueeze(0).to(device)

    segmentation_model.eval()

    with torch.no_grad():

        segmentation_output = segmentation_model(
            segmentation_input
        )

        segmentation_probability = torch.sigmoid(
            segmentation_output
        )[0, 0]

    # Existing project threshold = 0.60
    segmentation_mask = (
        segmentation_probability >= 0.60
    )

    # ========================================================
    # 3. DAMAGE AREA
    # ========================================================
    damage_pixels = segmentation_mask.sum().item()
    total_pixels = segmentation_mask.numel()

    damage_percentage = (
        damage_pixels / total_pixels
    ) * 100

    # ========================================================
    # 4. SEVERITY
    # ========================================================
    if damage_percentage < 5:
        severity = "Low"

    elif damage_percentage < 15:
        severity = "Moderate"

    elif damage_percentage < 30:
        severity = "High"

    else:
        severity = "Very High"

    # ========================================================
    # 5. ASSESSMENT SCORE
    # ========================================================
    assessment_score = (
        0.60 * damage_percentage
        +
        0.40 * classification_confidence
    )

    # ========================================================
    # 6. ASSESSMENT CATEGORY
    # ========================================================
    if assessment_score < 25:
        assessment_category = "Low Assessment"

    elif assessment_score < 50:
        assessment_category = "Moderate Assessment"

    elif assessment_score < 75:
        assessment_category = "High Assessment"

    else:
        assessment_category = "Very High Assessment"

    # ========================================================
    # 7. PROJECT-DEFINED INSURANCE STATUS
    # ========================================================
    if assessment_score >= 25:
        insurance_status = "Insurance Eligible"

    else:
        insurance_status = "Not Insurance Eligible"

    # ========================================================
    # RETURN
    # ========================================================
    return {
        "damage_type": damage_type,
        "classification_confidence": classification_confidence,
        "damage_percentage": damage_percentage,
        "severity": severity,
        "assessment_score": assessment_score,
        "assessment_category": assessment_category,
        "insurance_status": insurance_status
    }


print("======================================================")
print("predict_vehicle_damage() READY")
print("Classification transform: READY")
print("Segmentation transform: READY")
print("Segmentation threshold: 0.60")
print("======================================================")

